type CustomBrush struct {
	// Func is the color function that determines the color at each point.
	Func	ColorFunc

	// Name is an optional identifier for debugging and logging.
	Name	string
}

func (c RGBA) Color() color.Color {
	return color.NRGBA{
		R:	uint8(clamp255(c.R * 255)),
		G:	uint8(clamp255(c.G * 255)),
		B:	uint8(clamp255(c.B * 255)),
		A:	uint8(clamp255(c.A * 255)),
	}
}

func FromColor(c color.Color) RGBA {
	r, g, b, a := c.RGBA()
	if a == 0 {
		return RGBA{0, 0, 0, 0}
	}
	return RGBA{
		R:	float64(r) / float64(a),
		G:	float64(g) / float64(a),
		B:	float64(b) / float64(a),
		A:	float64(a) / 65535,
	}
}

func Hex(hex string) RGBA {
	if c, err := ParseHex(hex); err == nil {
		return c
	}
	return RGBA{R: 0, G: 0, B: 0, A: 1}
}

func (c RGBA) Lerp(other RGBA, t float64) RGBA {
	return RGBA{
		R:	c.R + (other.R-c.R)*t,
		G:	c.G + (other.G-c.G)*t,
		B:	c.B + (other.B-c.B)*t,
		A:	c.A + (other.A-c.A)*t,
	}
}

func ParseHex(hex string) (RGBA, error) {
	original := hex
	if hex != "" && hex[0] == '#' {
		hex = hex[1:]
	}

	var r, g, b, a uint32
	a = 255
	var valid bool

	switch len(hex) {
	case 3:	// RGB
		valid = parseHex(hex[0:1], &r) && parseHex(hex[1:2], &g) && parseHex(hex[2:3], &b)
		r, g, b = r*17, g*17, b*17
	case 4:	// RGBA
		valid = parseHex(hex[0:1], &r) && parseHex(hex[1:2], &g) && parseHex(hex[2:3], &b) && parseHex(hex[3:4], &a)
		r, g, b, a = r*17, g*17, b*17, a*17
	case 6:	// RRGGBB
		valid = parseHex(hex[0:2], &r) && parseHex(hex[2:4], &g) && parseHex(hex[4:6], &b)
	case 8:	// RRGGBBAA
		valid = parseHex(hex[0:2], &r) && parseHex(hex[2:4], &g) && parseHex(hex[4:6], &b) && parseHex(hex[6:8], &a)
	default:
		valid = false
	}

	if !valid {
		return RGBA{R: 0, G: 0, B: 0, A: 1}, fmt.Errorf("invalid hex color format: %q", original)
	}

	return RGBA{
		R:	float64(r) / 255,
		G:	float64(g) / 255,
		B:	float64(b) / 255,
		A:	float64(a) / 255,
	}, nil
}

func (c RGBA) Premultiply() RGBA {
	return RGBA{
		R:	c.R * c.A,
		G:	c.G * c.A,
		B:	c.B * c.A,
		A:	c.A,
	}
}

func RGB(r, g, b float64) RGBA {
	return RGBA{R: r, G: g, B: b, A: 1.0}
}

func RGBA2(r, g, b, a float64) RGBA {
	return RGBA{R: r, G: g, B: b, A: a}
}

func (c RGBA) Unpremultiply() RGBA {
	if c.A == 0 {
		return RGBA{R: 0, G: 0, B: 0, A: 0}
	}
	return RGBA{
		R:	c.R / c.A,
		G:	c.G / c.A,
		B:	c.B / c.A,
		A:	c.A,
	}
}

