	if a := Accelerator(); a != nil {
		c.warnGPUFallback("FlushGPU")
		return a.Flush(t)
	}
	return nil
}

func (c *Context) FlushGPUWithView(view gpucontext.TextureView, width, height uint32) error {
	t := c.gpuRenderTarget()
	if !view.IsNil() {
		t.View = view
		t.ViewWidth = width
		t.ViewHeight = height
	}
	rc := c.gpuCtxOps()
	if rc != nil {
		return rc.Flush(t)
	}
	if a := Accelerator(); a != nil {
		c.warnGPUFallback("FlushGPUWithView")
		return a.Flush(t)
	}
	return ErrFallbackToCPU
}

