		t.ViewWidth = width
		t.ViewHeight = height
	}
	if !damageRect.Empty() {
		t.DamageRects = []image.Rectangle{damageRect}
	}
	if rc := c.gpuCtxOps(); rc != nil {
		return rc.Flush(t)
