type Context struct {
	width		int	// logical width (user-facing)
	height		int	// logical height (user-facing)
	pixmap		*Pixmap
	renderer	Renderer

	// HiDPI support
	deviceScale	float64	// physical pixels per logical pixel (default 1.0)

	// Current state
	path		*Path
	paint		*Paint
	face		text.Face	// Current font face for text drawing
	clipStack	*clip.ClipStack	// Clipping stack
	gpuClipPath	*Path		// device-space clip path for GPU depth clipping (GPU-CLIP-003a)

	// Transform and state stack
	matrix		Matrix	// user transform (starts as Identity, user-space only)
	deviceMatrix	Matrix	// device scale transform (Identity when scale=1.0, NEVER modified by user)
	stack		[]Matrix
	clipStackDepth	[]int	// Tracks clip stack depth for each Push/Pop

	// Layer support
	layerStack	*layerStack	// Layer stack for compositing
	basePixmap	*Pixmap		// Base pixmap when layers are active

	// Mask support
	mask		*Mask	// Current alpha mask
	maskStack	[]*Mask	// Mask stack for Push/Pop

	// Per-frame damage tracking (ADR-021 Level 1).
	// List of per-operation bounding boxes — NOT a single union rect.
	// Each Fill/Stroke adds its own rect. Passed as-is to PresentWithDamage
	// for per-rect OS blit. Merged to bounding box if count exceeds threshold.
	frameDamageRects	[]image.Rectangle
	damageTrackingEnabled	bool

	// Pipeline mode
	pipelineMode	PipelineMode	// GPU pipeline selection mode

	// Rasterizer mode
	rasterizerMode	RasterizerMode	// CPU rasterizer selection mode

	// Anti-aliasing
	antiAlias	bool	// anti-aliasing enabled (default: true)
	antiAliasStack	[]bool	// Push/Pop stack for antiAlias state

	// Text rendering
	textMode		TextMode		// text strategy selection (default: Auto)
	outlineExtractor	*text.OutlineExtractor	// lazy: for transform-aware text (Strategy B)
	glyphCache		*text.GlyphCache	// lazy: cached glyph outlines for drawStringAsOutlines

	// Per-context GPU render context (isolated pending commands, clips, frame tracking).
	// Lazily created when GPURenderContextProvider is available.
	// Typed as gpuContextOps (defined in this package) to avoid circular import
	// with internal/gpu while maintaining type safety.
	gpuCtx			gpuContextOps
	gpuFallbackWarned	bool	// true after first global fallback warning (avoid log spam)

	// Lifecycle
	closed	bool	// Indicates whether Close has been called
}

func (c *Context) Clip() {
	if c.clipStack == nil {
		c.initClipStack()
	}

	// Path elements are in user-space; clip stack operates in device-space.
	// Transform through deviceMatrix to get device coordinates.
	devicePath := c.deviceSpacePath()
	clipVerbs, clipCoords := convertPathToClipVerbs(devicePath)

	// Push the path as a clip region
	_ = c.clipStack.PushPath(clipVerbs, clipCoords, true)	// anti-aliased by default

	// Store the device-space path for GPU depth clipping (GPU-CLIP-003a).
	// The GPU DepthClipPipeline fan-tessellates this path at draw time.
	c.gpuClipPath = devicePath.Clone()

	// Clear the path
	c.path.Clear()
}

func (c *Context) ClipPreserve() {
	if c.clipStack == nil {
		c.initClipStack()
	}

	// Path elements are in user-space; clip stack operates in device-space.
	devicePath := c.deviceSpacePath()
	clipVerbs, clipCoords := convertPathToClipVerbs(devicePath)

	// Push the path as a clip region
	_ = c.clipStack.PushPath(clipVerbs, clipCoords, true)	// anti-aliased by default

	// Store the device-space path for GPU depth clipping (GPU-CLIP-003a).
	c.gpuClipPath = devicePath.Clone()
	// Path is preserved
}

func (c *Context) ClipRect(x, y, w, h float64) {
	if c.clipStack == nil {
		c.initClipStack()
	}

	// Transform the rectangle corners to device coordinates.
	tm := c.totalMatrix()
	p1 := tm.TransformPoint(Pt(x, y))
	p2 := tm.TransformPoint(Pt(x+w, y+h))

	// Create clip rectangle in device coordinates
	rect := clip.NewRect(
		math.Min(p1.X, p2.X),
		math.Min(p1.Y, p2.Y),
		math.Abs(p2.X-p1.X),
		math.Abs(p2.Y-p1.Y),
	)

	c.clipStack.PushRect(rect)
}

func (c *Context) ClipRoundRect(x, y, w, h, radius float64) {
	if radius <= 0 {
		c.ClipRect(x, y, w, h)
		return
	}

	if c.clipStack == nil {
		c.initClipStack()
	}

	// Transform the rectangle corners to device coordinates.
	tm := c.totalMatrix()
	p1 := tm.TransformPoint(Pt(x, y))
	p2 := tm.TransformPoint(Pt(x+w, y+h))

	// Create clip rectangle in device coordinates.
	devX := math.Min(p1.X, p2.X)
	devY := math.Min(p1.Y, p2.Y)
	devW := math.Abs(p2.X - p1.X)
	devH := math.Abs(p2.Y - p1.Y)

	// Scale radius by the total transform scale factor.
	scaledRadius := radius * tm.ScaleFactor()

	// Clamp to half the smaller dimension.
	maxRadius := math.Min(devW, devH) / 2
	if scaledRadius > maxRadius {
		scaledRadius = maxRadius
	}

	rect := clip.NewRect(devX, devY, devW, devH)
	c.clipStack.PushRRect(rect, scaledRadius)
}

func (c *Context) ResetClip() {
	if c.clipStack == nil {
		return
	}

	// Reset to physical pixel bounds (clip stack operates in device-space).
	bounds := clip.NewRect(0, 0, float64(c.pixmap.Width()), float64(c.pixmap.Height()))
	c.clipStack.Reset(bounds)
	c.gpuClipPath = nil
}

func (p *ImagePattern) ColorAt(x, y float64) RGBA {
	// Apply inverse transform: device-space -> image-space.
	imgPt := p.inverse.TransformPoint(Pt(x, y))
	lx := imgPt.X
	ly := imgPt.Y

	// Get image bounds.
	imgW, imgH := p.image.Bounds()

	// Determine pattern region.
	patternW := p.w
	patternH := p.h
	if patternW == 0 {
		patternW = imgW
	}
	if patternH == 0 {
		patternH = imgH
	}

	if p.clamp {
		// Clamp mode: out-of-bounds returns transparent.
		ix := int(lx)
		iy := int(ly)
		if ix < 0 || ix >= patternW || iy < 0 || iy >= patternH {
			return RGBA{}
		}
		ix += p.x
		iy += p.y
		r, g, b, a := p.image.GetRGBA(ix, iy)
		col := RGBA{
			R:	float64(r) / 255.0,
			G:	float64(g) / 255.0,
			B:	float64(b) / 255.0,
			A:	float64(a) / 255.0,
		}
		if p.opacity > 0 && p.opacity < 1.0 {
			col.A *= p.opacity
		}
		return col
	}

	// Wrap coordinates to pattern region (tiling).
	px := int(lx) % patternW
	py := int(ly) % patternH
	if px < 0 {
		px += patternW
	}
	if py < 0 {
		py += patternH
	}

	// Add source region offset.
	px += p.x
	py += p.y

	// Sample the image.
	r, g, b, a := p.image.GetRGBA(px, py)
	col := RGBA{
		R:	float64(r) / 255.0,
		G:	float64(g) / 255.0,
		B:	float64(b) / 255.0,
		A:	float64(a) / 255.0,
	}
	if p.opacity > 0 && p.opacity < 1.0 {
		col.A *= p.opacity
	}
	return col
}

