}

func (c CubicBez) Subsegment(t0, t1 float64) CubicBez {
	p0 := c.Eval(t0)
	p3 := c.Eval(t1)

	// Calculate control points using derivative at endpoints
	// The derivative at t is: 3[(P1-P0)(1-t)^2 + 2(P2-P1)(1-t)t + (P3-P2)t^2]
	d0 := c.P1.Sub(c.P0)
	d1 := c.P2.Sub(c.P1)
	d2 := c.P3.Sub(c.P2)

	scale := (t1 - t0) / 3.0

	// Derivative at t0
	mt0 := 1.0 - t0
	deriv0 := Point{
		X:	3 * (d0.X*mt0*mt0 + 2*d1.X*mt0*t0 + d2.X*t0*t0),
		Y:	3 * (d0.Y*mt0*mt0 + 2*d1.Y*mt0*t0 + d2.Y*t0*t0),
	}
	p1 := Point{
		X:	p0.X + scale*deriv0.X,
		Y:	p0.Y + scale*deriv0.Y,
	}

	// Derivative at t1
	mt1 := 1.0 - t1
	deriv1 := Point{
		X:	3 * (d0.X*mt1*mt1 + 2*d1.X*mt1*t1 + d2.X*t1*t1),
		Y:	3 * (d0.Y*mt1*mt1 + 2*d1.Y*mt1*t1 + d2.Y*t1*t1),
	}
	p2 := Point{
		X:	p3.X - scale*deriv1.X,
		Y:	p3.Y - scale*deriv1.Y,
	}

	return CubicBez{P0: p0, P1: p1, P2: p2, P3: p3}
}

func (l Line) Subsegment(t0, t1 float64) Line {
	return Line{
		P0:	l.Eval(t0),
		P1:	l.Eval(t1),
	}
}

func (q QuadBez) Subsegment(t0, t1 float64) QuadBez {
	p0 := q.Eval(t0)
	p2 := q.Eval(t1)

	// Calculate the control point for the subsegment
	// Using the property that the tangent at any point is the lerp of
	// the control polygon edges
	d0 := q.P1.Sub(q.P0)
	d1 := q.P2.Sub(q.P1)
	dt := (t1 - t0)

	// Tangent direction at t0, scaled for the new segment
	tanDir := Point{
		X:	d0.X + t0*(d1.X-d0.X),
		Y:	d0.Y + t0*(d1.Y-d0.Y),
	}
	p1 := Point{
		X:	p0.X + dt*tanDir.X,
		Y:	p0.Y + dt*tanDir.Y,
	}

	return QuadBez{P0: p0, P1: p1, P2: p2}
}

func (c CubicBez) Tangent(t float64) Vec2 {
	deriv := c.Deriv()
	p := deriv.Eval(t)
	return Vec2(p)
}

func (r Rect) Union(other Rect) Rect {
	return Rect{
		Min:	Point{X: math.Min(r.Min.X, other.Min.X), Y: math.Min(r.Min.Y, other.Min.Y)},
		Max:	Point{X: math.Max(r.Max.X, other.Max.X), Y: math.Max(r.Max.Y, other.Max.Y)},
	}
}

func (r Rect) Width() float64 {
	return r.Max.X - r.Min.X
}

type Rect struct {
	Min, Max Point
}

type Line struct {
	P0, P1 Point
}

type QuadBez struct {
	P0, P1, P2 Point
}

type CubicBez struct {
	P0, P1, P2, P3 Point
}

func (d *Dash) Clone() *Dash {
	if d == nil {
		return nil
	}

	arrayCopy := make([]float64, len(d.Array))
	copy(arrayCopy, d.Array)

	return &Dash{
		Array:	arrayCopy,
		Offset:	d.Offset,
	}
}

func (d *Dash) IsDashed() bool {
	if d == nil || len(d.Array) == 0 {
		return false
	}

	// Check if any dash has positive length
	for _, l := range d.Array {
		if l > 0 {
			return true
		}
	}
	return false
}

func NewDash(lengths ...float64) *Dash {
	if len(lengths) == 0 {
		return nil
	}

	// Check if all values are zero or negative
	allZeroOrNeg := true
	for _, l := range lengths {
		if l > 0 {
			allZeroOrNeg = false
			break
		}
	}
	if allZeroOrNeg {
		return nil
	}

	// Take absolute values for any negative lengths
	normalized := make([]float64, len(lengths))
	for i, l := range lengths {
		normalized[i] = math.Abs(l)
	}

	return &Dash{
		Array:	normalized,
		Offset:	0,
	}
}

func (d *Dash) NormalizedOffset() float64 {
	if d == nil {
		return 0
	}

	patternLen := d.PatternLength()
	if patternLen <= 0 {
		return 0
	}

	offset := math.Mod(d.Offset, patternLen)
	if offset < 0 {
		offset += patternLen
	}
	return offset
}

func (d *Dash) PatternLength() float64 {
	if d == nil || len(d.Array) == 0 {
		return 0
	}

	var total float64
	for _, l := range d.Array {
		total += l
	}

	// If odd number of elements, pattern is duplicated
	if len(d.Array)%2 != 0 {
		total *= 2
	}

	return total
}

func (d *Dash) Scale(factor float64) *Dash {
	if d == nil || factor <= 0 {
		return d
	}

	scaledArray := make([]float64, len(d.Array))
	for i, l := range d.Array {
		scaledArray[i] = l * factor
	}

	return &Dash{
		Array:	scaledArray,
		Offset:	d.Offset * factor,
	}
}

func (d *Dash) WithOffset(offset float64) *Dash {
	if d == nil {
		return nil
	}
	return &Dash{
		Array:	d.Array,
		Offset:	offset,
	}
}

type Dash struct {
	// Array contains alternating dash/gap lengths.
	// If the array has an odd number of elements, it is logically duplicated
	// to create an even-length pattern (e.g., [5] becomes [5, 5]).
	Array	[]float64

	// Offset is the starting offset into the pattern.
	// The stroke begins at this point in the pattern cycle.
	Offset	float64
}

func SetDeviceProvider(provider gpucontext.DeviceProvider) error {
	return gg.SetAcceleratorDeviceProvider(provider)
}

type ColorStop struct {
	Offset	float64	// Position in gradient, 0.0 to 1.0
	Color	RGBA	// Color at this position
}

func (g *LinearGradientBrush) AddColorStop(offset float64, c RGBA) *LinearGradientBrush {
	g.Stops = append(g.Stops, ColorStop{Offset: offset, Color: c})
	g.sorted = false	// invalidate cached sort
	return g
}

func (g *LinearGradientBrush) ColorAt(x, y float64) RGBA {
	// Handle zero-length gradient (start == end)
	dx := g.End.X - g.Start.X
	dy := g.End.Y - g.Start.Y
	lengthSq := dx*dx + dy*dy

	if lengthSq == 0 {
		return firstStopColor(g.ensureSorted())
	}

	// Project point onto the gradient line
	// t = dot(P - Start, End - Start) / |End - Start|^2
	px := x - g.Start.X
	py := y - g.Start.Y
	t := (px*dx + py*dy) / lengthSq

	return colorAtOffset(g.ensureSorted(), t, g.Extend)
}

func NewLinearGradientBrush(x0, y0, x1, y1 float64) *LinearGradientBrush {
	return &LinearGradientBrush{
		Start:	Point{X: x0, Y: y0},
		End:	Point{X: x1, Y: y1},
		Stops:	nil,
		Extend:	ExtendPad,
	}
}

func (g *LinearGradientBrush) SetExtend(mode ExtendMode) *LinearGradientBrush {
	g.Extend = mode
	return g
}

type LinearGradientBrush struct {
	Start	Point		// Start point of the gradient
	End	Point		// End point of the gradient
	Stops	[]ColorStop	// Color stops defining the gradient
	Extend	ExtendMode	// How gradient extends beyond bounds

	// sortedStops caches stops sorted by offset. Populated lazily on first
	// ColorAt call. Invalidated by AddColorStop (sorted set to false).
	sortedStops	[]ColorStop
	sorted		bool
}

func (g *RadialGradientBrush) AddColorStop(offset float64, c RGBA) *RadialGradientBrush {
	g.Stops = append(g.Stops, ColorStop{Offset: offset, Color: c})
	g.sorted = false	// invalidate cached sort
	return g
}

func (g *RadialGradientBrush) ColorAt(x, y float64) RGBA {
	// Handle degenerate gradient (zero radius difference)
	radiusDiff := g.EndRadius - g.StartRadius
	if radiusDiff == 0 {
		return firstStopColor(g.ensureSorted())
	}

	t := g.computeT(x, y)
	return colorAtOffset(g.ensureSorted(), t, g.Extend)
}

func NewRadialGradientBrush(cx, cy, startRadius, endRadius float64) *RadialGradientBrush {
	center := Point{X: cx, Y: cy}
	return &RadialGradientBrush{
		Center:		center,
		Focus:		center,	// Default focus at center
		StartRadius:	startRadius,
		EndRadius:	endRadius,
		Stops:		nil,
		Extend:		ExtendPad,
	}
}

func (g *RadialGradientBrush) SetExtend(mode ExtendMode) *RadialGradientBrush {
	g.Extend = mode
	return g
}

func (g *RadialGradientBrush) SetFocus(fx, fy float64) *RadialGradientBrush {
	g.Focus = Point{X: fx, Y: fy}
	return g
}

type RadialGradientBrush struct {
	Center		Point		// Center of the gradient circle
	Focus		Point		// Focal point (can differ from center)
	StartRadius	float64		// Inner radius where gradient begins (t=0)
	EndRadius	float64		// Outer radius where gradient ends (t=1)
	Stops		[]ColorStop	// Color stops defining the gradient
	Extend		ExtendMode	// How gradient extends beyond bounds

	// sortedStops caches stops sorted by offset. Populated lazily on first
	// ColorAt call. Invalidated by AddColorStop (sorted set to false).
	sortedStops	[]ColorStop
	sorted		bool
}

func (g *SweepGradientBrush) AddColorStop(offset float64, c RGBA) *SweepGradientBrush {
	g.Stops = append(g.Stops, ColorStop{Offset: offset, Color: c})
	g.sorted = false	// invalidate cached sort
	return g
}

func (g *SweepGradientBrush) ColorAt(x, y float64) RGBA {
	// Handle point at center (undefined angle)
	dx := x - g.Center.X
	dy := y - g.Center.Y
	if dx == 0 && dy == 0 {
		return firstStopColor(g.ensureSorted())
	}

	// Calculate angle from center to point
	// atan2 returns angle in range [-Pi, Pi]
	angle := math.Atan2(dy, dx)

	// Normalize angle relative to start angle
	t := g.angleToT(angle)

	return colorAtOffset(g.ensureSorted(), t, g.Extend)
}

func NewSweepGradientBrush(cx, cy, startAngle float64) *SweepGradientBrush {
	return &SweepGradientBrush{
		Center:		Point{X: cx, Y: cy},
		StartAngle:	startAngle,
		EndAngle:	startAngle + 2*math.Pi,	// Full rotation by default
		Stops:		nil,
		Extend:		ExtendPad,
	}
}

func (g *SweepGradientBrush) SetEndAngle(endAngle float64) *SweepGradientBrush {
	g.EndAngle = endAngle
	return g
}

func (g *SweepGradientBrush) SetExtend(mode ExtendMode) *SweepGradientBrush {
	g.Extend = mode
	return g
}

type SweepGradientBrush struct {
	Center		Point		// Center of the sweep
	StartAngle	float64		// Start angle in radians
	EndAngle	float64		// End angle in radians (if 0, defaults to StartAngle + 2*Pi)
	Stops		[]ColorStop	// Color stops defining the gradient
	Extend		ExtendMode	// How gradient extends beyond bounds

	// sortedStops caches stops sorted by offset. Populated lazily on first
	// ColorAt call. Invalidated by AddColorStop (sorted set to false).
	sortedStops	[]ColorStop
	sorted		bool
}

func (c *Canvas) Close() error {
	if c.closed {
		return nil
	}
	c.closed = true

	// Untrack from ResourceTracker if auto-registered, to prevent double-close.
	if c.tracked {
		if tracker, ok := c.provider.(resourceTracker); ok {
			tracker.UntrackResource(c)
		}
		c.tracked = false
	}

	// Note: no need to clear surface target — per-pass View routing handles
	// target selection. Session-level surfaceView is no longer set.

	// Destroy textures (current and any deferred old texture).
	destroyTexture(c.oldTexture)
	c.oldTexture = nil
	destroyTexture(c.texture)
	c.texture = nil

	// Close gg context
	if c.ctx != nil {
		_ = c.ctx.Close()
		c.ctx = nil
	}

	c.provider = nil
	return nil
}

func (c *Canvas) Context() *gg.Context {
	if c.closed {
		return nil
	}
	return c.ctx
}

func (c *Canvas) DeviceScale() float64 {
	if c.ctx == nil {
		return 1.0
	}
	return c.ctx.DeviceScale()
}

func (c *Canvas) Draw(fn func(*gg.Context)) error {
	if c.closed {
		return ErrCanvasClosed
	}
	gg.BeginAcceleratorFrame()
	c.ctx.Push()
	c.ctx.Identity()
	c.ctx.ClearPath()
	c.ctx.ResetFrameDamage()
	fn(c.ctx)
	c.ctx.Pop()
	c.MarkDirty()
	return nil
}

func (c *Canvas) EnsureGPUTexture(dc RenderTarget) error {
	if c.texture == nil || c.closed {
		return nil
	}
	if _, ok := c.texture.(*pendingTexture); !ok {
		return nil
	}
	promoted, err := c.promoteIfPending(c.texture, dc)
	if err != nil {
		return err
	}
	c.texture = promoted
	return nil
}

func (c *Canvas) Flush() (any, error) {
	if c.closed {
		return nil, ErrCanvasClosed
	}

	// Flush pending GPU shapes to pixel buffer before reading pixel data.
	// Errors are logged but not fatal — CPU fallback may have already rendered.
	if err := c.ctx.FlushGPU(); err != nil {
		gg.Logger().Warn("FlushGPU error", "err", err)
	}

	return c.FlushPixmap()
}

func (c *Canvas) FlushPixmap() (any, error) {
	if c.closed {
		return nil, ErrCanvasClosed
	}

	if c.sizeChanged {
		c.deferTextureDestruction()
		c.sizeChanged = false
	}

	if !c.dirty && c.texture != nil {
		return c.texture, nil
	}

	pixmap := c.ctx.ResizeTarget()
	data := pixmap.Data()

	if c.texture == nil {
		c.texture = c.createTexture(data)
		c.dirty = false
		c.dirtyRect = image.Rectangle{}
		return c.texture, nil
	}

	if err := c.uploadTexture(pixmap, data); err != nil {
		return nil, err
	}

	c.dirty = false
	c.dirtyRect = image.Rectangle{}
	return c.texture, nil
}

func (c *Canvas) Height() int {
	return c.height
}

func (c *Canvas) IsDirty() bool {
	return c.dirty
}

func (c *Canvas) LastDamage() image.Rectangle {
	return c.dirtyRect
}

func (c *Canvas) LastDamageRects() []image.Rectangle {
	return c.ctx.FrameDamage()
}

func (c *Canvas) MarkDirty() {
	c.dirty = true
	c.dirtyRect = image.Rect(0, 0, c.ctx.PixelWidth(), c.ctx.PixelHeight())
}

func (c *Canvas) MarkDirtyRegion(r image.Rectangle) {
	if r.Empty() {
		return
	}
	if c.dirtyRect.Empty() {
		c.dirtyRect = r
	} else {
		c.dirtyRect = c.dirtyRect.Union(r)
	}
	c.dirty = true
}

