type Paint struct {
	// solidColor stores the solid color inline (Skia fColor4f pattern).
	// When isSolid is true, this is the authoritative color source —
	// Brush and Pattern are nil, avoiding interface boxing allocations.
	solidColor	RGBA

	// isSolid is true when the paint represents a single solid color
	// stored in solidColor. When true, Brush and Pattern are nil.
	isSolid	bool

	// Pattern is the fill or stroke pattern.
	//
	// Deprecated: Use Brush instead. Pattern is maintained for backward compatibility.
	Pattern	Pattern

	// Brush is the fill or stroke brush (vello/peniko pattern).
	// When both Brush and Pattern are set, Brush takes precedence.
	// Use SetBrush() to set the brush, which also updates Pattern for compatibility.
	Brush	Brush

	// LineWidth is the width of strokes.
	//
	// Deprecated: Use Stroke.Width instead. Maintained for backward compatibility.
	LineWidth	float64

	// LineCap is the shape of line endpoints.
	//
	// Deprecated: Use Stroke.Cap instead. Maintained for backward compatibility.
	LineCap	LineCap

	// LineJoin is the shape of line joins.
	//
	// Deprecated: Use Stroke.Join instead. Maintained for backward compatibility.
	LineJoin	LineJoin

	// MiterLimit is the miter limit for sharp joins.
	//
	// Deprecated: Use Stroke.MiterLimit instead. Maintained for backward compatibility.
	MiterLimit	float64

	// FillRule is the fill rule for paths
	FillRule	FillRule

	// Antialias enables anti-aliasing
	Antialias	bool

	// Stroke is the unified stroke style configuration.
	// This is the preferred way to configure stroke properties.
	// When Stroke is set, it takes precedence over the individual
	// LineWidth, LineCap, LineJoin, and MiterLimit fields.
	Stroke	*Stroke

	// TransformScale is the scale factor from the current transform matrix.
	// Used internally by the renderer to determine effective stroke width.
	// Set automatically by Context.Stroke() before rendering.
	TransformScale	float64

	// ClipCoverage is a function that returns the clip coverage (0-255)
	// at a given pixel coordinate. When non-nil, the renderer multiplies
	// pixel alpha by this coverage to apply the clip mask.
	// Set automatically by Context before rendering when a clip is active.
	ClipCoverage	func(x, y float64) byte

	// MaskCoverage is a function that returns the alpha mask coverage (0-255)
	// at a given pixel coordinate. When non-nil, the renderer multiplies
	// pixel alpha by this coverage to apply the alpha mask.
	// Uses int coords because masks are pixel-aligned (no sub-pixel sampling).
	// Set automatically by Context before rendering when a mask is active.
	MaskCoverage	func(x, y int) uint8
}

func (p *SolidPainter) PaintSpan(dest []RGBA, _, _ int, length int) {
	for i := 0; i < length && i < len(dest); i++ {
		dest[i] = p.Color
	}
}

func (p *FuncPainter) PaintSpan(dest []RGBA, x, y, length int) {
	fy := float64(y) + 0.5
	for i := 0; i < length && i < len(dest); i++ {
		dest[i] = p.Fn(float64(x+i)+0.5, fy)
	}
}

func PainterFromPaint(paint *Paint) Painter {
	// Fast path: inline solid color (no interface dispatch).
	if paint.isSolid {
		return &SolidPainter{Color: paint.solidColor}
	}
	// Check Brush first (takes precedence)
	if paint.Brush != nil {
		if sb, ok := paint.Brush.(SolidBrush); ok {
			return &SolidPainter{Color: sb.Color}
		}
		// Check if the Brush itself implements Painter (power-user opt-in)
		if p, ok := paint.Brush.(Painter); ok {
			return p
		}
		return &FuncPainter{Fn: paint.Brush.ColorAt}
	}
	// Fall back to Pattern
	if paint.Pattern != nil {
		if sp, ok := paint.Pattern.(*SolidPattern); ok {
			return &SolidPainter{Color: sp.Color}
		}
		return &FuncPainter{Fn: paint.Pattern.ColorAt}
	}
	return &SolidPainter{Color: Black}
}

type SolidPainter struct {
	Color RGBA
}

type FuncPainter struct {
	Fn func(x, y float64) RGBA
}

type Painter interface {
	// PaintSpan fills dest with colors for pixels starting at (x, y) for length pixels.
	PaintSpan(dest []RGBA, x, y, length int)
}

func (p *Path) Append(other *Path) {
	if other == nil || len(other.verbs) == 0 {
		return
	}
	p.verbs = append(p.verbs, other.verbs...)
	p.coords = append(p.coords, other.coords...)
	p.current = other.current
	p.start = other.start
}

func (p *Path) Arc(cx, cy, r, angle1, angle2 float64) {
	// Normalize angles
	const twoPi = 2 * math.Pi
	for angle2 < angle1 {
		angle2 += twoPi
	}

	// Split into multiple cubic Bezier curves
	// Maximum 90 degrees per segment
	const maxAngle = math.Pi / 2
	numSegments := int(math.Ceil((angle2 - angle1) / maxAngle))
	angleStep := (angle2 - angle1) / float64(numSegments)

	for i := 0; i < numSegments; i++ {
		a1 := angle1 + float64(i)*angleStep
		a2 := a1 + angleStep
		p.arcSegment(cx, cy, r, a1, a2)
	}
}

func (p *Path) Bounds() image.Rectangle {
	if !p.boundsValid {
		return image.Rectangle{}
	}
	return image.Rect(
		int(math.Floor(p.boundsMinX)),
		int(math.Floor(p.boundsMinY)),
		int(math.Ceil(p.boundsMaxX)),
		int(math.Ceil(p.boundsMaxY)),
	)
}

func (p *Path) Circle(cx, cy, r float64) {
	// Magic constant for circle approximation with cubic Beziers
	const k = 0.5522847498307936	// 4/3 * (sqrt(2) - 1)
	offset := r * k

	p.MoveTo(cx+r, cy)
	p.CubicTo(cx+r, cy+offset, cx+offset, cy+r, cx, cy+r)
	p.CubicTo(cx-offset, cy+r, cx-r, cy+offset, cx-r, cy)
	p.CubicTo(cx-r, cy-offset, cx-offset, cy-r, cx, cy-r)
	p.CubicTo(cx+offset, cy-r, cx+r, cy-offset, cx+r, cy)
	p.Close()
}

func (p *Path) Clear() {
	p.verbs = p.verbs[:0]
	p.coords = p.coords[:0]
	p.start = Point{}
	p.current = Point{}
	p.boundsValid = false
}

func (p *Path) Clone() *Path {
	result := &Path{
		verbs:		make([]PathVerb, len(p.verbs)),
		coords:		make([]float64, len(p.coords)),
		start:		p.start,
		current:	p.current,
	}
	copy(result.verbs, p.verbs)
	copy(result.coords, p.coords)
	return result
}

func (p *Path) Close() {
	p.verbs = append(p.verbs, Close)
	p.current = p.start
}

func (p *Path) Coords() []float64 {
	return p.coords
}

func (p *Path) CurrentPoint() Point {
	return p.current
}

func (p *Path) HasCurrentPoint() bool {
	return len(p.verbs) > 0
}

func (p *Path) HasCurves() bool {
	for _, v := range p.verbs {
		if v == QuadTo || v == CubicTo {
			return true
		}
	}
	return false
}

func (p *Path) Iterate(fn func(verb PathVerb, coords []float64)) {
	ci := 0
	for _, v := range p.verbs {
		n := verbCoordCount(v)
		if n > 0 {
			fn(v, p.coords[ci:ci+n])
		} else {
			fn(v, nil)
		}
		ci += n
	}
}

func (p *Path) LineTo(x, y float64) {
	p.verbs = append(p.verbs, LineTo)
	p.coords = append(p.coords, x, y)
	p.expandBounds(x, y)
	p.current = Pt(x, y)
}

func NewPath() *Path {
	p := &Path{}
	p.verbs = p.verbsBuf[:0]
	p.coords = p.coordsBuf[:0]
	return p
}

