func (p *Pixmap) GetPixel(x, y int) RGBA {
	if x < 0 || x >= p.width || y < 0 || y >= p.height {
		return Transparent
	}
	i := (y*p.width + x) * 4
	a := float64(p.data[i+3]) / 255
	if a <= 0 {
		return RGBA{0, 0, 0, 0}
	}
	return RGBA{
		R:	float64(p.data[i+0]) / 255 / a,
		G:	float64(p.data[i+1]) / 255 / a,
		B:	float64(p.data[i+2]) / 255 / a,
		A:	a,
	}
}

