func (r Rect) Contains(x, y float64) bool {
	return x >= r.MinX && x <= r.MaxX && y >= r.MinY && y <= r.MaxY
}

func (m Matrix) Determinant() float64 {
	return m.A*m.E - m.B*m.D
}

func (r Rect) Height() float64 {
	return r.MaxY - r.MinY
}

func Identity() Matrix {
	return Matrix{
		A:	1, B: 0, C: 0,
		D:	0, E: 1, F: 0,
	}
}

func (r Rect) Inset(dx, dy float64) Rect {
	return Rect{
		MinX:	r.MinX + dx,
		MinY:	r.MinY + dy,
		MaxX:	r.MaxX - dx,
		MaxY:	r.MaxY - dy,
	}
}

func (r Rect) Intersect(other Rect) Rect {
	result := Rect{
		MinX:	math.Max(r.MinX, other.MinX),
		MinY:	math.Max(r.MinY, other.MinY),
		MaxX:	math.Min(r.MaxX, other.MaxX),
		MaxY:	math.Min(r.MaxY, other.MaxY),
	}
	if result.IsEmpty() {
		return Rect{}
	}
	return result
}

func (m Matrix) Invert() Matrix {
	det := m.A*m.E - m.B*m.D
	if math.Abs(det) < 1e-10 {
		return Identity()
	}

	invDet := 1.0 / det
	return Matrix{
		A:	m.E * invDet,
		B:	-m.B * invDet,
		C:	(m.B*m.F - m.C*m.E) * invDet,
		D:	-m.D * invDet,
		E:	m.A * invDet,
		F:	(m.C*m.D - m.A*m.F) * invDet,
	}
}

func (r Rect) IsEmpty() bool {
	return r.MaxX <= r.MinX || r.MaxY <= r.MinY
}

func (m Matrix) IsIdentity() bool {
	const eps = 1e-10
	return math.Abs(m.A-1) < eps && math.Abs(m.B) < eps && math.Abs(m.C) < eps &&
		math.Abs(m.D) < eps && math.Abs(m.E-1) < eps && math.Abs(m.F) < eps
}

func (m Matrix) IsTranslation() bool {
	const eps = 1e-10
	return math.Abs(m.A-1) < eps && math.Abs(m.B) < eps &&
		math.Abs(m.D) < eps && math.Abs(m.E-1) < eps
}

func (m Matrix) Multiply(other Matrix) Matrix {
	return Matrix{
		A:	m.A*other.A + m.B*other.D,
		B:	m.A*other.B + m.B*other.E,
		C:	m.A*other.C + m.B*other.F + m.C,
		D:	m.D*other.A + m.E*other.D,
		E:	m.D*other.B + m.E*other.E,
		F:	m.D*other.C + m.E*other.F + m.F,
	}
}

func NewRect(x, y, width, height float64) Rect {
	return Rect{
		MinX:	x,
		MinY:	y,
		MaxX:	x + width,
		MaxY:	y + height,
	}
}

func NewRectFromPoints(x1, y1, x2, y2 float64) Rect {
	return Rect{
		MinX:	math.Min(x1, x2),
		MinY:	math.Min(y1, y2),
		MaxX:	math.Max(x1, x2),
		MaxY:	math.Max(y1, y2),
	}
}

func (r Rect) Offset(dx, dy float64) Rect {
	return Rect{
		MinX:	r.MinX + dx,
		MinY:	r.MinY + dy,
		MaxX:	r.MaxX + dx,
		MaxY:	r.MaxY + dy,
	}
}

func Rotate(angle float64) Matrix {
	cos := math.Cos(angle)
	sin := math.Sin(angle)
	return Matrix{
		A:	cos, B: -sin, C: 0,
		D:	sin, E: cos, F: 0,
	}
}

func Scale(sx, sy float64) Matrix {
	return Matrix{
		A:	sx, B: 0, C: 0,
		D:	0, E: sy, F: 0,
	}
}

func (m Matrix) ScaleFactor() float64 {
	// Calculate the two singular values of the 2x2 part.
	sx := math.Sqrt(m.A*m.A + m.D*m.D)
	sy := math.Sqrt(m.B*m.B + m.E*m.E)
	if sx > sy {
		return sx
	}
	return sy
}

func Shear(x, y float64) Matrix {
	return Matrix{
		A:	1, B: x, C: 0,
		D:	y, E: 1, F: 0,
	}
}

func (m Matrix) TransformPoint(x, y float64) (float64, float64) {
	return m.A*x + m.B*y + m.C, m.D*x + m.E*y + m.F
}

func (m Matrix) TransformVector(x, y float64) (float64, float64) {
	return m.A*x + m.B*y, m.D*x + m.E*y
}

func Translate(x, y float64) Matrix {
	return Matrix{
		A:	1, B: 0, C: x,
		D:	0, E: 1, F: y,
	}
}

func (m Matrix) Translation() (x, y float64) {
	return m.C, m.F
}

func (r Rect) Union(other Rect) Rect {
	return Rect{
		MinX:	math.Min(r.MinX, other.MinX),
		MinY:	math.Min(r.MinY, other.MinY),
		MaxX:	math.Max(r.MaxX, other.MaxX),
		MaxY:	math.Max(r.MaxY, other.MaxY),
	}
}

func (r Rect) Width() float64 {
	return r.MaxX - r.MinX
}

func (r Rect) X() float64 {
	return r.MinX
}

func (r Rect) Y() float64 {
	return r.MinY
}

type Matrix struct {
	A, B, C	float64
	D, E, F	float64
}

type Rect struct {
	MinX, MinY	float64
	MaxX, MaxY	float64
}

func (p *ResourcePool) AddBrush(brush Brush) BrushRef {
	p.brushes = append(p.brushes, brush)
	// #nosec G115 -- pool size is bounded by available memory, well under uint32 max
	return BrushRef(uint32(len(p.brushes) - 1))
}

func (p *ResourcePool) AddFont(face text.Face) FontRef {
	p.fonts = append(p.fonts, face)
	// #nosec G115 -- pool size is bounded by available memory, well under uint32 max
	return FontRef(uint32(len(p.fonts) - 1))
}

func (p *ResourcePool) AddImage(img image.Image) ImageRef {
	p.images = append(p.images, img)
	// #nosec G115 -- pool size is bounded by available memory, well under uint32 max
	return ImageRef(uint32(len(p.images) - 1))
}

func (p *ResourcePool) AddPath(path *gg.Path) PathRef {
	if path == nil {
		// Add nil as-is to preserve the reference
		p.paths = append(p.paths, nil)
		// #nosec G115 -- pool size is bounded by available memory, well under uint32 max
		return PathRef(uint32(len(p.paths) - 1))
	}
	// Clone path to ensure immutability
	cloned := path.Clone()
	p.paths = append(p.paths, cloned)
	// #nosec G115 -- pool size is bounded by available memory, well under uint32 max
	return PathRef(uint32(len(p.paths) - 1))
}

func (p *ResourcePool) BrushCount() int {
	return len(p.brushes)
}

func (p *ResourcePool) Clear() {
	p.paths = p.paths[:0]
	p.brushes = p.brushes[:0]
	p.images = p.images[:0]
	p.fonts = p.fonts[:0]
}

func (p *ResourcePool) Clone() *ResourcePool {
	clone := &ResourcePool{
		paths:		make([]*gg.Path, len(p.paths)),
		brushes:	make([]Brush, len(p.brushes)),
		images:		make([]image.Image, len(p.images)),
		fonts:		make([]text.Face, len(p.fonts)),
	}

	// Clone paths (mutable)
	for i, path := range p.paths {
		if path != nil {
			clone.paths[i] = path.Clone()
		}
	}

	// Copy brushes directly (immutable structs)
	copy(clone.brushes, p.brushes)

	// Copy images and fonts by reference (already immutable)
	copy(clone.images, p.images)
	copy(clone.fonts, p.fonts)

	return clone
}

