func (c *LayerCache) Contains(hash uint64) bool {
	c.mu.RLock()
	defer c.mu.RUnlock()
	_, ok := c.entries[hash]
	return ok
}

func DefaultLayerCache() *LayerCache {
	return NewLayerCache(DefaultMaxSizeMB)
}

func (c *LayerCache) EntryCount() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return len(c.entries)
}

func (c *LayerCache) Get(hash uint64) (*gg.Pixmap, bool) {
	c.mu.RLock()
	_, ok := c.entries[hash]
	c.mu.RUnlock()

	if !ok {
		c.misses.Add(1)
		return nil, false
	}

	// Move to front (requires write lock)
	c.mu.Lock()
	// Re-check after acquiring write lock (entry may have been evicted)
	entry, ok := c.entries[hash]
	if !ok {
		c.mu.Unlock()
		c.misses.Add(1)
		return nil, false
	}
	c.lru.MoveToFront(entry.element)
	entry.lastUsed = time.Now()
	pixmap := entry.pixmap
	c.mu.Unlock()

	c.hits.Add(1)
	return pixmap, true
}

func (c *LayerCache) GetVersion(hash uint64) (uint64, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	if entry, ok := c.entries[hash]; ok {
		return entry.version, true
	}
	return 0, false
}

func (c *LayerCache) Invalidate(hash uint64) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if entry, ok := c.entries[hash]; ok {
		c.lru.Remove(entry.element)
		c.size -= entry.size
		delete(c.entries, hash)
		c.evictions.Add(1)
	}
}

func (c *LayerCache) InvalidateAll() {
	c.mu.Lock()
	defer c.mu.Unlock()

	evicted := uint64(len(c.entries))
	c.entries = make(map[uint64]*CacheEntry)
	c.lru.Init()
	c.size = 0

	if evicted > 0 {
		c.evictions.Add(evicted)
	}
}

func (c *LayerCache) MaxSize() int64 {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.maxSize
}

func NewLayerCache(maxSizeMB int) *LayerCache {
	if maxSizeMB <= 0 {
		maxSizeMB = DefaultMaxSizeMB
	}
	return &LayerCache{
		entries:	make(map[uint64]*CacheEntry),
		lru:		list.New(),
		maxSize:	int64(maxSizeMB) * bytesPerMB,
	}
}

func (c *LayerCache) Put(hash uint64, pixmap *gg.Pixmap, version uint64) {
	if pixmap == nil {
		return
	}

	entrySize := pixmapSize(pixmap)
	if entrySize <= 0 {
		return
	}

	// Don't cache if single entry exceeds budget
	if entrySize > c.maxSize {
		return
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	// Check if entry already exists
	if existing, ok := c.entries[hash]; ok {
		// Update existing entry
		c.size -= existing.size
		c.lru.Remove(existing.element)
	}

	// Evict entries until we have space
	c.evictUntilSize(c.maxSize - entrySize)

	// Create new entry
	entry := &CacheEntry{
		hash:		hash,
		pixmap:		pixmap,
		size:		entrySize,
		version:	version,
		lastUsed:	time.Now(),
	}
	entry.element = c.lru.PushFront(entry)
	c.entries[hash] = entry
	c.size += entrySize
}

func (c *LayerCache) ResetStats() {
	c.hits.Store(0)
	c.misses.Store(0)
	c.evictions.Store(0)
}

func (c *LayerCache) SetMaxSize(mb int) {
	if mb <= 0 {
		mb = DefaultMaxSizeMB
	}
	newMaxSize := int64(mb) * bytesPerMB

	c.mu.Lock()
	defer c.mu.Unlock()

	c.maxSize = newMaxSize
	c.evictUntilSize(newMaxSize)
}

func (c *LayerCache) Size() int64 {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.size
}

func (c *LayerCache) Trim(targetSize int64) {
	if targetSize < 0 {
		targetSize = 0
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	c.evictUntilSize(targetSize)
}

type CacheStats struct {
	// Size is the current memory usage in bytes.
	Size	int64
	// MaxSize is the memory budget in bytes.
	MaxSize	int64
	// Entries is the number of cached entries.
	Entries	int
	// Hits is the number of cache hits.
	Hits	uint64
	// Misses is the number of cache misses.
	Misses	uint64
	// HitRate is the cache hit rate (0.0 to 1.0).
	HitRate	float64
	// Evictions is the number of entries evicted.
	Evictions	uint64
}

func (dt *DamageTracker) ComputeDamage(objects []TaggedBounds) image.Rectangle {
	if dt.firstFrame {
		dt.firstFrame = false
		dt.storeBounds(objects)
		// First frame: caller should render everything.
		// Return zero rect — caller detects first frame via separate flag or renders full.
		return image.Rectangle{}
	}

	var damage image.Rectangle
	seen := make(map[uint64]struct{}, len(objects))

	for _, obj := range objects {
		seen[obj.ID] = struct{}{}
		if prev, exists := dt.prevBounds[obj.ID]; exists {
			if prev != obj.Rect {
				damage = damage.Union(prev).Union(obj.Rect)
			}
		} else {
			damage = damage.Union(obj.Rect)
		}
	}

	for id, prev := range dt.prevBounds {
		if _, exists := seen[id]; !exists {
			damage = damage.Union(prev)
		}
	}

	dt.storeBounds(objects)
	return damage
}

