func (d *Decoder) AntiAlias() bool {
	if d.drawIdx+1 > len(d.enc.drawData) {
		return true	// default: AA enabled
	}
	val := d.enc.drawData[d.drawIdx]
	d.drawIdx++
	return val != 0
}

func (d *Decoder) Brush() (r, g, b, a float32) {
	if d.pathIdx+4 > len(d.enc.pathData) {
		return 0, 0, 0, 1
	}
	r = d.enc.pathData[d.pathIdx]
	g = d.enc.pathData[d.pathIdx+1]
	b = d.enc.pathData[d.pathIdx+2]
	a = d.enc.pathData[d.pathIdx+3]
	d.pathIdx += 4
	return r, g, b, a
}

func (d *Decoder) CubicTo() (c1x, c1y, c2x, c2y, x, y float32) {
	if d.pathIdx+6 > len(d.enc.pathData) {
		return 0, 0, 0, 0, 0, 0
	}
	c1x = d.enc.pathData[d.pathIdx]
	c1y = d.enc.pathData[d.pathIdx+1]
	c2x = d.enc.pathData[d.pathIdx+2]
	c2y = d.enc.pathData[d.pathIdx+3]
	x = d.enc.pathData[d.pathIdx+4]
	y = d.enc.pathData[d.pathIdx+5]
	d.pathIdx += 6
	return c1x, c1y, c2x, c2y, x, y
}

func (d *Decoder) Encoding() *Encoding {
	return d.enc
}

func (d *Decoder) Fill() (brush Brush, style FillStyle) {
	if d.drawIdx+2 > len(d.enc.drawData) {
		return Brush{}, FillNonZero
	}

	brushIdx := d.enc.drawData[d.drawIdx]
	styleVal := d.enc.drawData[d.drawIdx+1]
	d.drawIdx += 2

	if int(brushIdx) < len(d.enc.brushes) {
		brush = d.enc.brushes[brushIdx]
	}
	style = FillStyle(styleVal)
	return brush, style
}

func (d *Decoder) FillRoundRect() (brush Brush, style FillStyle, rect Rect, rx, ry float32) {
	if d.drawIdx+2 > len(d.enc.drawData) {
		return Brush{}, FillNonZero, Rect{}, 0, 0
	}

	brushIdx := d.enc.drawData[d.drawIdx]
	styleVal := d.enc.drawData[d.drawIdx+1]
	d.drawIdx += 2

	if int(brushIdx) < len(d.enc.brushes) {
		brush = d.enc.brushes[brushIdx]
	}
	style = FillStyle(styleVal)

	if d.pathIdx+6 > len(d.enc.pathData) {
		return brush, style, Rect{}, 0, 0
	}

	rect = Rect{
		MinX:	d.enc.pathData[d.pathIdx],
		MinY:	d.enc.pathData[d.pathIdx+1],
		MaxX:	d.enc.pathData[d.pathIdx+2],
		MaxY:	d.enc.pathData[d.pathIdx+3],
	}
	rx = d.enc.pathData[d.pathIdx+4]
	ry = d.enc.pathData[d.pathIdx+5]
	d.pathIdx += 6

	return brush, style, rect, rx, ry
}

func (d *Decoder) HasMore() bool {
	return d.enc != nil && d.tagIdx < len(d.enc.tags)
}

func (d *Decoder) Image() (imageIndex uint32, transform Affine) {
	if d.drawIdx+1 > len(d.enc.drawData) {
		return 0, IdentityAffine()
	}

	imageIndex = d.enc.drawData[d.drawIdx]
	d.drawIdx++

	if d.transIdx < len(d.enc.transforms) {
		transform = d.enc.transforms[d.transIdx]
		d.transIdx++
	} else {
		transform = IdentityAffine()
	}
	return imageIndex, transform
}

func (d *Decoder) LineTo() (x, y float32) {
	if d.pathIdx+2 > len(d.enc.pathData) {
		return 0, 0
	}
	x = d.enc.pathData[d.pathIdx]
	y = d.enc.pathData[d.pathIdx+1]
	d.pathIdx += 2
	return x, y
}

func (d *Decoder) MoveTo() (x, y float32) {
	if d.pathIdx+2 > len(d.enc.pathData) {
		return 0, 0
	}
	x = d.enc.pathData[d.pathIdx]
	y = d.enc.pathData[d.pathIdx+1]
	d.pathIdx += 2
	return x, y
}

func NewDecoder(enc *Encoding) *Decoder {
	if enc == nil {
		return nil
	}
	return &Decoder{
		enc: enc,
	}
}

func (d *Decoder) Next() bool {
	if d.enc == nil || d.tagIdx >= len(d.enc.tags) {
		return false
	}

	d.currentTag = d.enc.tags[d.tagIdx]
	d.tagIdx++
	return true
}

func (d *Decoder) Peek() Tag {
	if d.tagIdx >= len(d.enc.tags) {
		return 0
	}
	return d.enc.tags[d.tagIdx]
}

func (d *Decoder) Position() int {
	return d.tagIdx
}

func (d *Decoder) PushLayer() (blend BlendMode, alpha float32) {
	if d.drawIdx+2 > len(d.enc.drawData) {
		return BlendNormal, 1.0
	}

	blendVal := d.enc.drawData[d.drawIdx]
	alphaBits := d.enc.drawData[d.drawIdx+1]
	d.drawIdx += 2

	blend = BlendMode(blendVal)
	alpha = math.Float32frombits(alphaBits)
	return blend, alpha
}

func (d *Decoder) QuadTo() (cx, cy, x, y float32) {
	if d.pathIdx+4 > len(d.enc.pathData) {
		return 0, 0, 0, 0
	}
	cx = d.enc.pathData[d.pathIdx]
	cy = d.enc.pathData[d.pathIdx+1]
	x = d.enc.pathData[d.pathIdx+2]
	y = d.enc.pathData[d.pathIdx+3]
	d.pathIdx += 4
	return cx, cy, x, y
}

func (d *Decoder) SkipPath() {
	for d.Next() {
		switch d.currentTag {
		case TagMoveTo:
			d.pathIdx += 2
		case TagLineTo:
			d.pathIdx += 2
		case TagQuadTo:
			d.pathIdx += 4
		case TagCubicTo:
			d.pathIdx += 6
		case TagEndPath:
			return
		}
	}
}

func (d *Decoder) Stroke() (brush Brush, style *StrokeStyle) {
	if d.drawIdx+5 > len(d.enc.drawData) {
		return Brush{}, DefaultStrokeStyle()
	}

	brushIdx := d.enc.drawData[d.drawIdx]
	widthBits := d.enc.drawData[d.drawIdx+1]
	miterBits := d.enc.drawData[d.drawIdx+2]
	capVal := d.enc.drawData[d.drawIdx+3]
	joinVal := d.enc.drawData[d.drawIdx+4]
	d.drawIdx += 5

	if int(brushIdx) < len(d.enc.brushes) {
		brush = d.enc.brushes[brushIdx]
	}

	style = &StrokeStyle{
		Width:		math.Float32frombits(widthBits),
		MiterLimit:	math.Float32frombits(miterBits),
		Cap:		LineCap(capVal),
		Join:		LineJoin(joinVal),
	}
	return brush, style
}

func (d *Decoder) Tag() Tag {
	return d.currentTag
}

func (d *Decoder) Transform() Affine {
	if d.transIdx >= len(d.enc.transforms) {
		return IdentityAffine()
	}
	t := d.enc.transforms[d.transIdx]
	d.transIdx++
	return t
}

comments:
Decoder provides sequential decoding of an Encoding's command stream.
It tracks position indices across all data streams (tags, paths, draws, transforms)
and provides methods to read each command type's associated data.

The decoder is designed for efficient rendering playback, supporting both
full traversal and selective decoding for tile-based rendering.

Example usage:

dec := NewDecoder(encoding)
for dec.Next() {
switch dec.Tag() {
case TagMoveTo:
x, y := dec.MoveTo()
// handle move
case TagLineTo:
x, y := dec.LineTo()
// handle line
case TagFill:
brush, style := dec.Fill()
// handle fill
}
}

code:
type Decoder struct {
	enc	*Encoding

	// Stream position indices
	tagIdx		int
	pathIdx		int
	drawIdx		int
	transIdx	int
	textIdx		int

	// Current tag being processed
	currentTag	Tag
}

func AffineFromMatrix(m gg.Matrix) Affine {
	return Affine{
		A:	float32(m.A),
		B:	float32(m.B),
		C:	float32(m.C),
		D:	float32(m.D),
		E:	float32(m.E),
		F:	float32(m.F),
	}
}

func (e *Encoding) Append(other *Encoding) {
	e.AppendWithImages(other, 0)
}

func (e *Encoding) AppendWithImages(other *Encoding, imageOffset uint32) {
	if other == nil || len(other.tags) == 0 {
		return
	}

	// Calculate brush index offset for the appended encoding
	//nolint:gosec // brush slice length is bounded, overflow not possible in practice
	brushOffset := uint32(len(e.brushes))

	// Append tags directly
	e.tags = append(e.tags, other.tags...)

	// Append path data directly
	e.pathData = append(e.pathData, other.pathData...)

	// Append draw data with adjusted brush indices
	// We need to adjust brush references in fill/stroke commands
	drawDataStart := len(e.drawData)
	e.drawData = append(e.drawData, other.drawData...)

	// Adjust brush indices in the appended draw data.
	// Also adjust brush indices embedded in textData for TagText commands.
	drawIdx := 0
	textDataStart := len(e.textData)
	e.textData = append(e.textData, other.textData...)
	textOff := 0
	for _, tag := range other.tags {
		switch tag {
		case TagFill:
			if drawIdx < len(other.drawData) {
				e.drawData[drawDataStart+drawIdx] += brushOffset
			}
			drawIdx += 2
		case TagFillRoundRect:
			if drawIdx < len(other.drawData) {
				e.drawData[drawDataStart+drawIdx] += brushOffset
			}
			drawIdx += 2
		case TagStroke:
			if drawIdx < len(other.drawData) {
				e.drawData[drawDataStart+drawIdx] += brushOffset
			}
			drawIdx += 5
		case TagPushLayer:
			drawIdx += 2
		case TagSetAntiAlias:
			drawIdx++	// 1 uint32: 0 or 1
		case TagImage:
			if imageOffset > 0 && drawIdx < len(other.drawData) {
				e.drawData[drawDataStart+drawIdx] += imageOffset
			}
			drawIdx++
		case TagText:
			if textOff+glyphRunDataSize <= len(other.textData) {
				glyphCount := int(binary.LittleEndian.Uint16(other.textData[textOff+12:]))
				textLen := int(binary.LittleEndian.Uint16(other.textData[textOff+28:]))
				// Adjust brush index (at offset 24 in GlyphRunData)
				brushIdxOff := textDataStart + textOff + 24
				oldBrush := binary.LittleEndian.Uint32(e.textData[brushIdxOff:])
				binary.LittleEndian.PutUint32(e.textData[brushIdxOff:], oldBrush+brushOffset)
				textOff += glyphRunDataSize + glyphCount*glyphEntrySize + textLen
			}
		}
	}

	// Append transforms
	e.transforms = append(e.transforms, other.transforms...)

	// Append brushes
	e.brushes = append(e.brushes, other.brushes...)

	// Union bounds
	e.bounds = e.bounds.Union(other.bounds)

	// Update statistics
	e.pathCount += other.pathCount
	e.shapeCount += other.shapeCount
}

func (e *Encoding) AppendWithTranslation(other *Encoding, dx, dy float32, imageOffset uint32) {
	if other == nil || len(other.tags) == 0 {
		return
	}
	if dx == 0 && dy == 0 {
		e.AppendWithImages(other, imageOffset)
		return
	}

	//nolint:gosec // brush slice length is bounded
	brushOffset := uint32(len(e.brushes))

	e.tags = append(e.tags, other.tags...)

	pathStart := len(e.pathData)
	e.pathData = append(e.pathData, other.pathData...)

	drawDataStart := len(e.drawData)
	e.drawData = append(e.drawData, other.drawData...)

	pathIdx := 0
	drawIdx := 0
	for _, tag := range other.tags {
		switch tag {
		// --- Coordinate tags: offset pathData by (dx, dy) ---

		case TagMoveTo, TagLineTo:
			e.pathData[pathStart+pathIdx] += dx
			e.pathData[pathStart+pathIdx+1] += dy
			pathIdx += 2

		case TagQuadTo:
			for i := 0; i < 4; i += 2 {
				e.pathData[pathStart+pathIdx+i] += dx
				e.pathData[pathStart+pathIdx+i+1] += dy
			}
			pathIdx += 4

		case TagCubicTo:
			for i := 0; i < 6; i += 2 {
				e.pathData[pathStart+pathIdx+i] += dx
				e.pathData[pathStart+pathIdx+i+1] += dy
			}
			pathIdx += 6

		case TagFillRoundRect:
			// 6 floats: minX, minY, maxX, maxY (offset), radiusX, radiusY (no offset).
			e.pathData[pathStart+pathIdx] += dx
			e.pathData[pathStart+pathIdx+1] += dy
			e.pathData[pathStart+pathIdx+2] += dx
			e.pathData[pathStart+pathIdx+3] += dy
			pathIdx += 6
			if drawIdx < len(other.drawData) {
				e.drawData[drawDataStart+drawIdx] += brushOffset
			}
			drawIdx += 2

		// --- Non-coordinate pathData: skip without offset ---

		case TagBrush:
			pathIdx += 4	// 4 float32: R, G, B, A — not coordinates

		// --- Draw data only (no pathData) ---

		case TagFill:
			if drawIdx < len(other.drawData) {
				e.drawData[drawDataStart+drawIdx] += brushOffset
			}
			drawIdx += 2

		case TagStroke:
			if drawIdx < len(other.drawData) {
				e.drawData[drawDataStart+drawIdx] += brushOffset
			}
			drawIdx += 5	// brush + width + miterLimit + cap + join

		case TagPushLayer:
			drawIdx += 2	// blend mode + alpha

		case TagSetAntiAlias:
			drawIdx++	// 1 uint32: 0 or 1, no coordinate data

		case TagImage:
			if imageOffset > 0 && drawIdx < len(other.drawData) {
				e.drawData[drawDataStart+drawIdx] += imageOffset
			}
			drawIdx++	// image index only; transform is in transforms stream

		case TagText:
			// Text data is in the textData stream. Handled in a second pass below.

		// --- Marker/structural tags: zero pathData, zero drawData ---

		case TagTransform:
			// Transform data is in the separate transforms stream, not pathData.
			// Handled below (copied verbatim).

		case TagBeginPath, TagEndPath, TagClosePath,
			TagPopLayer, TagBeginClip, TagEndClip:
			// Pure markers — no data in any stream.

		default:
			panic(fmt.Sprintf("scene.AppendWithTranslation: unhandled tag 0x%02X (%s) — update switch to handle pathData/drawData layout for this tag", byte(tag), tag))
		}
	}

	e.appendTextDataWithTranslation(other, brushOffset, dx, dy)

	// Transforms copied verbatim — see architecture note above.
	e.transforms = append(e.transforms, other.transforms...)

	e.brushes = append(e.brushes, other.brushes...)

	ob := other.bounds
	ob.MinX += dx
	ob.MinY += dy
	ob.MaxX += dx
	ob.MaxY += dy
	e.bounds = e.bounds.Union(ob)

	e.pathCount += other.pathCount
	e.shapeCount += other.shapeCount
}

