}

func (e *Encoding) DrawData() []uint32 {
	return e.drawData
}

func EmptyRect() Rect {
	return Rect{
		MinX:	math.MaxFloat32,
		MinY:	math.MaxFloat32,
		MaxX:	-math.MaxFloat32,
		MaxY:	-math.MaxFloat32,
