	Join		LineJoin
}

type Brush struct {
	Kind	BrushKind
	Color	gg.RGBA	// For solid brushes
	// Additional fields for gradients/images would go here
}

type Rect struct {
	MinX, MinY	float32
	MaxX, MaxY	float32
