func NewGPUSceneRenderer(dc *gg.Context) *GPUSceneRenderer {
	return &GPUSceneRenderer{dc: dc}
}

func (r *GPUSceneRenderer) RenderScene(scene *Scene) error {	//nolint:gocyclo,cyclop,funlen,gocognit // tag dispatch across all scene command types
	if scene == nil {
		return nil
	}

	enc := scene.Encoding()
	if enc == nil || len(enc.Tags()) == 0 {
		return nil
	}

	dec := NewDecoder(enc)
	if dec == nil {
		return nil
	}

	dc := r.dc
	path := gg.NewPath()

	// Save the initial matrix so we can compose scene transforms correctly
	// and restore the original state after rendering.
	// Scene transforms use dc.SetTransform() (direct replacement) instead of
	// dc.Push()/Pop() to avoid interfering with clip Push/Pop nesting.
	baseMatrix := dc.GetTransform()

	for dec.Next() {
		switch dec.Tag() {
		case TagTransform:
			a := dec.Transform()
			// Apply scene transform composed with the context's base matrix.
			// Scene transforms are absolute (full accumulated affine from the
			// encoder, e.g. currentTransform.Multiply(perDrawTransform)), so we
			// compose with baseMatrix to preserve any parent context transform
			// (e.g. dc.Translate() called before RenderScene).
			//
			// Using Push/Pop here would corrupt clip state when TagTransform
			// appears inside a BeginClip/EndClip region: the transform's Pop
			// would undo the clip's Push, removing the clip before content is
			// drawn. SetTransform avoids this by not touching the state stack.
			sceneMatrix := gg.Matrix{
				A:	float64(a.A), B: float64(a.B), C: float64(a.C),
				D:	float64(a.D), E: float64(a.E), F: float64(a.F),
			}
			dc.SetTransform(baseMatrix.Multiply(sceneMatrix))

		case TagBeginPath:
			path.Clear()

		case TagMoveTo:
			x, y := dec.MoveTo()
			path.MoveTo(float64(x), float64(y))

		case TagLineTo:
			x, y := dec.LineTo()
			path.LineTo(float64(x), float64(y))

		case TagQuadTo:
			cx, cy, x, y := dec.QuadTo()
			path.QuadraticTo(float64(cx), float64(cy), float64(x), float64(y))

		case TagCubicTo:
			c1x, c1y, c2x, c2y, x, y := dec.CubicTo()
			path.CubicTo(float64(c1x), float64(c1y), float64(c2x), float64(c2y), float64(x), float64(y))

		case TagClosePath:
			path.Close()

		case TagEndPath:
			// Path building complete; fill/stroke tag follows.

		case TagFill:
			brush, style := dec.Fill()
			applySceneBrush(dc, brush)
			if style == FillEvenOdd {
				dc.SetFillRule(gg.FillRuleEvenOdd)
			} else {
				dc.SetFillRule(gg.FillRuleNonZero)
			}
			_ = dc.FillPath(path)
			path.Clear()

		case TagFillRoundRect:
			brush, style, rect, rx, ry := dec.FillRoundRect()
			applySceneBrush(dc, brush)
			if style == FillEvenOdd {
				dc.SetFillRule(gg.FillRuleEvenOdd)
			} else {
				dc.SetFillRule(gg.FillRuleNonZero)
			}
			radius := float64(rx)
			if ry > rx {
				radius = float64(ry)
			}
			dc.DrawRoundedRectangle(
				float64(rect.MinX), float64(rect.MinY),
				float64(rect.MaxX-rect.MinX), float64(rect.MaxY-rect.MinY),
				radius,
			)
			_ = dc.Fill()

		case TagStroke:
			brush, style := dec.Stroke()
			applySceneBrush(dc, brush)
			if style != nil {
				if style.Width > 0 {
					dc.SetLineWidth(float64(style.Width))
				}
				dc.SetLineCap(gg.LineCap(style.Cap))
				dc.SetLineJoin(gg.LineJoin(style.Join))
				if style.MiterLimit > 0 {
					dc.SetMiterLimit(float64(style.MiterLimit))
				}
			}
			_ = dc.StrokePath(path)
			path.Clear()

		case TagPushLayer:
			blend, alpha := dec.PushLayer()
			dc.PushLayer(gg.BlendMode(blend), float64(alpha))

		case TagPopLayer:
			dc.PopLayer()

		case TagBeginClip:
			// Push state before clip so EndClip can restore the previous clip
			// level AND the transform that was active at clip time. Push/Pop
			// here is correct: clips are strictly nested and each BeginClip
			// has exactly one EndClip. No intermediate Pop can occur because
			// TagTransform uses SetTransform (not Push/Pop).
			dc.Push()
			// Detect rectangular clips → hardware scissor (ClipRect).
			// Non-rect clips → general path clip (depth buffer on GPU).
			// ClipRect uses PushRect → IsRectOnly()=true → hardware scissor.
			// Clip() uses PushPath → IsRectOnly()=false → depth clip path
			// which may not be available in all rendering contexts.
			shape := gg.DetectShape(path)
			if shape.Kind == gg.ShapeRect {
				x := shape.CenterX - shape.Width/2
				y := shape.CenterY - shape.Height/2
				dc.ClipRect(x, y, shape.Width, shape.Height)
			} else {
				dc.DrawPath(path)
				dc.Clip()
				dc.ClearPath()
			}
			path.Clear()

		case TagEndClip:
			dc.Pop()

		case TagSetAntiAlias:
			aa := dec.AntiAlias()
			dc.SetAntiAlias(aa)

		case TagText:
			run, glyphs, str, brush := dec.Text()
			r.resolveText(scene, run, glyphs, str, brush)

		case TagImage:
			imageIndex, imgTransform := dec.Image()
			r.resolveImage(scene, imageIndex, imgTransform)

		default:
			// Unknown tags are skipped by the decoder advancing tagIdx.
		}
	}

	// Restore the original matrix. Unlike the previous Push/Pop approach,
	// SetTransform is a direct replacement so we restore explicitly.
	dc.SetTransform(baseMatrix)

	return nil
}

type GPUSceneRenderer struct {
	dc *gg.Context
}

func (s *LayerStack) AcquireLayer() *LayerState {
	return s.pool.get()
}

func (s *LayerStack) All() []*LayerState {
	return s.layers
}

func (s *ClipStack) CombinedBounds() Rect {
	if len(s.clips) == 0 {
		return Rect{
			MinX:	-1e30,
			MinY:	-1e30,
			MaxX:	1e30,
			MaxY:	1e30,
		}	// No clip = infinite bounds
	}

	result := s.clips[0].Bounds
	for i := 1; i < len(s.clips); i++ {
		// Intersect bounds
		result = Rect{
			MinX:	max32(result.MinX, s.clips[i].Bounds.MinX),
			MinY:	max32(result.MinY, s.clips[i].Bounds.MinY),
			MaxX:	min32(result.MaxX, s.clips[i].Bounds.MaxX),
			MaxY:	min32(result.MaxY, s.clips[i].Bounds.MaxY),
		}
		if result.IsEmpty() {
			return EmptyRect()
		}
	}

	return result
}

func (cs *ClipState) Contains(x, y float32) bool {
	if cs.Bounds.IsEmpty() {
		return false
	}
	return x >= cs.Bounds.MinX && x <= cs.Bounds.MaxX &&
		y >= cs.Bounds.MinY && y <= cs.Bounds.MaxY
}

func (s *ClipStack) Contains(x, y float32) bool {
	for _, clip := range s.clips {
		if !clip.Contains(x, y) {
			return false
		}
	}
	return true
}

func (s *ClipStack) Depth() int {
	return len(s.clips)
}

func (s *LayerStack) Depth() int {
	return len(s.layers)
}

func (ls *LayerState) HasClip() bool {
	return ls.Clip != nil
}

func (cs *ClipState) Intersects(r Rect) bool {
	if cs.Bounds.IsEmpty() || r.IsEmpty() {
		return false
	}
	return !(r.MaxX < cs.Bounds.MinX || r.MinX > cs.Bounds.MaxX ||
		r.MaxY < cs.Bounds.MinY || r.MinY > cs.Bounds.MaxY)
}

func (s *ClipStack) Intersects(r Rect) bool {
	for _, clip := range s.clips {
		if !clip.Intersects(r) {
			return false
		}
	}
	return true
}

func (k LayerKind) IsClipOnly() bool {
	return k == LayerClip
}

func (ls *LayerState) IsEmpty() bool {
	if ls.Kind == LayerClip {
		return ls.Clip == nil
	}
	return ls.Encoding == nil || ls.Encoding.IsEmpty()
}

func (s *ClipStack) IsEmpty() bool {
	return len(s.clips) == 0
}

func (s *LayerStack) IsRoot() bool {
	return len(s.layers) == 1
}

func (k LayerKind) NeedsOffscreen() bool {
	return k == LayerFiltered
}

func NewClipLayer(clip Shape) *LayerState {
	return &LayerState{
		Kind:		LayerClip,
		BlendMode:	BlendNormal,
		Alpha:		1.0,
		Clip:		clip,
		Encoding:	nil,	// Clip layers don't need their own encoding
		Bounds:		EmptyRect(),
		Transform:	IdentityAffine(),
	}
}

func NewClipStack() *ClipStack {
	return &ClipStack{
		clips: make([]*ClipState, 0, 4),
	}
}

func NewClipState(shape Shape, transform Affine) *ClipState {
	var bounds Rect
	if shape != nil {
		bounds = shape.Bounds()
		// Transform bounds if needed
		if !transform.IsIdentity() {
			// Transform all four corners and compute new bounds
			corners := [][2]float32{
				{bounds.MinX, bounds.MinY},
				{bounds.MaxX, bounds.MinY},
				{bounds.MaxX, bounds.MaxY},
				{bounds.MinX, bounds.MaxY},
			}
			bounds = EmptyRect()
			for _, c := range corners {
				x, y := transform.TransformPoint(c[0], c[1])
				bounds = bounds.UnionPoint(x, y)
			}
		}
	} else {
		bounds = EmptyRect()
	}

	return &ClipState{
		Shape:		shape,
		Bounds:		bounds,
		Transform:	transform,
	}
}

func NewFilteredLayer(blend BlendMode, alpha float32) *LayerState {
	return &LayerState{
		Kind:		LayerFiltered,
		BlendMode:	blend,
		Alpha:		clampAlpha(alpha),
		Encoding:	NewEncoding(),
		Bounds:		EmptyRect(),
		Transform:	IdentityAffine(),
	}
}

func NewLayerStack() *LayerStack {
	stack := &LayerStack{
		layers:	make([]*LayerState, 0, 8),
		pool:	newLayerPool(),
	}
	// Create root layer
	root := stack.pool.get()
	root.Kind = LayerRegular
	root.BlendMode = BlendNormal
	root.Alpha = 1.0
	stack.layers = append(stack.layers, root)
	return stack
}

func NewLayerState(kind LayerKind, blend BlendMode, alpha float32) *LayerState {
	return &LayerState{
		Kind:		kind,
		BlendMode:	blend,
		Alpha:		clampAlpha(alpha),
		Encoding:	NewEncoding(),
		Bounds:		EmptyRect(),
		Transform:	IdentityAffine(),
	}
}

func (s *ClipStack) Pop() *ClipState {
	if len(s.clips) == 0 {
		return nil
	}
	clip := s.clips[len(s.clips)-1]
	s.clips = s.clips[:len(s.clips)-1]
	return clip
}

func (s *LayerStack) Pop() *LayerState {
	if len(s.layers) <= 1 {
		return nil	// Cannot pop root layer
	}
	layer := s.layers[len(s.layers)-1]
	s.layers = s.layers[:len(s.layers)-1]
	return layer
}

func (s *ClipStack) Push(clip *ClipState) {
	s.clips = append(s.clips, clip)
}

func (s *LayerStack) Push(layer *LayerState) {
	s.layers = append(s.layers, layer)
}

func (s *LayerStack) ReleaseLayer(layer *LayerState) {
	s.pool.put(layer)
}

func (s *LayerStack) Reset() {
	// Return all non-root layers to pool
	for i := len(s.layers) - 1; i > 0; i-- {
		s.pool.put(s.layers[i])
	}
	s.layers = s.layers[:1]

	// Reset root layer
	if len(s.layers) > 0 {
		s.layers[0].Reset()
	}
}

func (ls *LayerState) Reset() {
	ls.Kind = LayerRegular
	ls.BlendMode = BlendNormal
	ls.Alpha = 1.0
	ls.Clip = nil
	if ls.Encoding != nil {
		ls.Encoding.Reset()
	}
	ls.Bounds = EmptyRect()
	ls.Transform = IdentityAffine()
	ls.ClipStackDepth = 0
}

func (s *ClipStack) Reset() {
	s.clips = s.clips[:0]
}

func (s *LayerStack) Root() *LayerState {
	if len(s.layers) == 0 {
		return nil
	}
	return s.layers[0]
}

func (k LayerKind) String() string {
	switch k {
	case LayerRegular:
		return "Regular"
	case LayerFiltered:
		return "Filtered"
	case LayerClip:
		return "Clip"
	default:
		return unknownStr
	}
}

func (s *ClipStack) Top() *ClipState {
	if len(s.clips) == 0 {
		return nil
	}
	return s.clips[len(s.clips)-1]
}

func (s *LayerStack) Top() *LayerState {
	if len(s.layers) == 0 {
		return nil
	}
	return s.layers[len(s.layers)-1]
}

func (ls *LayerState) UpdateBounds(r Rect) {
	ls.Bounds = ls.Bounds.Union(r)
}

type LayerState struct {
	// Kind identifies the type of layer
	Kind	LayerKind

	// BlendMode specifies how this layer composites with layers below
	BlendMode	BlendMode

	// Alpha is the layer opacity (0.0 to 1.0)
	Alpha	float32

	// Clip is the optional clip shape for this layer.
	// If nil, the layer has no clip (infinite bounds).
	Clip	Shape

	// Encoding holds the layer's drawing commands.
	// This is populated as drawing commands are added to the scene
	// while this layer is active.
	Encoding	*Encoding

	// Bounds tracks the cumulative bounding box of layer content.
	// This is updated as content is added.
	Bounds	Rect

	// Transform is the transform active when the layer was pushed.
	// Used to restore transform state on pop.
	Transform	Affine

	// ClipStackDepth records the clip stack depth when layer was pushed.
	// Used to restore clip state on pop.
	ClipStackDepth	int
}

type LayerStack struct {
	layers	[]*LayerState
	pool	*layerPool
}

type ClipState struct {
	// Shape is the clip shape
	Shape	Shape

	// Bounds is the clip bounds (for quick rejection)
	Bounds	Rect

	// Transform is the transform that was active when clip was pushed
	Transform	Affine
}

type ClipStack struct {
	clips []*ClipState
}

func (p *Path) Arc(cx, cy, rx, ry, startAngle, endAngle float32, sweepClockwise bool) *Path {
	// Normalize angles
	if sweepClockwise && endAngle < startAngle {
		endAngle += 2 * math.Pi
	} else if !sweepClockwise && startAngle < endAngle {
		startAngle += 2 * math.Pi
	}

	// Calculate start point
	startX := cx + rx*float32(math.Cos(float64(startAngle)))
	startY := cy + ry*float32(math.Sin(float64(startAngle)))
	p.MoveTo(startX, startY)

	// Calculate sweep angle
	sweep := endAngle - startAngle
	if !sweepClockwise {
		sweep = -sweep
	}

	// Split into quarter arcs (max 90 degrees each) for better approximation
	numArcs := int(math.Ceil(math.Abs(float64(sweep)) / (math.Pi / 2)))
	if numArcs < 1 {
		numArcs = 1
	}

	arcAngle := sweep / float32(numArcs)
	currentAngle := startAngle

	for i := 0; i < numArcs; i++ {
		nextAngle := currentAngle + arcAngle
		p.arcSegment(cx, cy, rx, ry, currentAngle, nextAngle)
		currentAngle = nextAngle
	}

	return p
}

func (p *Path) Bounds() Rect {
	return p.bounds
}

func (p *Path) Circle(cx, cy, r float32) *Path {
	return p.Ellipse(cx, cy, r, r)
}

func (p *Path) Close() *Path {
	p.verbs = append(p.verbs, Close)
	p.cursor = p.start
	return p
}

func (p *Path) Contains(px, py float32) bool {
	// Quick bounds check
	if !p.bounds.IsEmpty() {
		if px < p.bounds.MinX || px > p.bounds.MaxX ||
			py < p.bounds.MinY || py > p.bounds.MaxY {
			return false
		}
	}

	// Count winding number
	winding := 0

	// Track current position and subpath start
	var curX, curY float32
	var startX, startY float32

	pointIdx := 0

	for _, verb := range p.verbs {
		switch verb {
		case MoveTo:
			// Close previous subpath if any
			if curX != startX || curY != startY {
				winding += windingSegment(curX, curY, startX, startY, px, py)
			}
			startX = p.points[pointIdx]
			startY = p.points[pointIdx+1]
			curX, curY = startX, startY
			pointIdx += 2

		case LineTo:
			nextX := p.points[pointIdx]
			nextY := p.points[pointIdx+1]
			winding += windingSegment(curX, curY, nextX, nextY, px, py)
			curX, curY = nextX, nextY
			pointIdx += 2

		case QuadTo:
			// Approximate quad with lines for containment test
			cx := p.points[pointIdx]
			cy := p.points[pointIdx+1]
			x := p.points[pointIdx+2]
			y := p.points[pointIdx+3]

			// Subdivide quadratic into lines
			winding += windingQuad(curX, curY, cx, cy, x, y, px, py)
			curX, curY = x, y
			pointIdx += 4

		case CubicTo:
			// Approximate cubic with lines for containment test
			c1x := p.points[pointIdx]
			c1y := p.points[pointIdx+1]
			c2x := p.points[pointIdx+2]
			c2y := p.points[pointIdx+3]
			x := p.points[pointIdx+4]
			y := p.points[pointIdx+5]

			winding += windingCubic(curX, curY, c1x, c1y, c2x, c2y, x, y, px, py)
			curX, curY = x, y
			pointIdx += 6

		case Close:
			// Close the subpath
			if curX != startX || curY != startY {
				winding += windingSegment(curX, curY, startX, startY, px, py)
			}
			curX, curY = startX, startY
		}
	}

	// Close final subpath if not explicitly closed
	if curX != startX || curY != startY {
		winding += windingSegment(curX, curY, startX, startY, px, py)
	}

	return winding != 0
}

func (p *Path) CubicTo(c1x, c1y, c2x, c2y, x, y float32) *Path {
	p.verbs = append(p.verbs, CubicTo)
	p.points = append(p.points, c1x, c1y, c2x, c2y, x, y)
	p.bounds = p.bounds.UnionPoint(c1x, c1y)
	p.bounds = p.bounds.UnionPoint(c2x, c2y)
	p.bounds = p.bounds.UnionPoint(x, y)
	// For accurate bounds, we should compute curve extrema,
	// but union with control points is a conservative approximation
	p.cursor = [2]float32{x, y}
	return p
}

func (p *Path) Elements() iter.Seq[PathElement] {
	return func(yield func(PathElement) bool) {
		pointIdx := 0

		for _, verb := range p.verbs {
			var elem PathElement
			elem.Verb = verb

			switch verb {
			case MoveTo, LineTo:
				elem.Points = []Point{
					{p.points[pointIdx], p.points[pointIdx+1]},
				}
				pointIdx += 2

			case QuadTo:
				elem.Points = []Point{
					{p.points[pointIdx], p.points[pointIdx+1]},
					{p.points[pointIdx+2], p.points[pointIdx+3]},
				}
				pointIdx += 4

			case CubicTo:
				elem.Points = []Point{
					{p.points[pointIdx], p.points[pointIdx+1]},
					{p.points[pointIdx+2], p.points[pointIdx+3]},
					{p.points[pointIdx+4], p.points[pointIdx+5]},
				}
				pointIdx += 6

			case Close:
				elem.Points = nil
			}

			if !yield(elem) {
				return
			}
		}
	}
}

func (p *Path) ElementsWithCursor() iter.Seq2[Point, PathElement] {
	return func(yield func(Point, PathElement) bool) {
		pointIdx := 0
		cursor := Point{0, 0}

		for _, verb := range p.verbs {
			var elem PathElement
			elem.Verb = verb
			prevCursor := cursor

			switch verb {
			case MoveTo:
				elem.Points = []Point{
					{p.points[pointIdx], p.points[pointIdx+1]},
				}
				cursor = elem.Points[0]
				pointIdx += 2

			case LineTo:
				elem.Points = []Point{
					{p.points[pointIdx], p.points[pointIdx+1]},
				}
				cursor = elem.Points[0]
				pointIdx += 2

			case QuadTo:
				elem.Points = []Point{
					{p.points[pointIdx], p.points[pointIdx+1]},
					{p.points[pointIdx+2], p.points[pointIdx+3]},
				}
				cursor = elem.Points[1]
				pointIdx += 4

			case CubicTo:
				elem.Points = []Point{
					{p.points[pointIdx], p.points[pointIdx+1]},
					{p.points[pointIdx+2], p.points[pointIdx+3]},
					{p.points[pointIdx+4], p.points[pointIdx+5]},
				}
				cursor = elem.Points[2]
				pointIdx += 6

			case Close:
				elem.Points = nil
				// cursor returns to subpath start (handled by caller if needed)
			}

			if !yield(prevCursor, elem) {
				return
			}
		}
	}
}

func (p *Path) Ellipse(cx, cy, rx, ry float32) *Path {
	// Magic number for approximating circular arcs with cubic beziers
	k := float32(0.5522847498)
	kx := k * rx
	ky := k * ry

	// Start at the right edge
	p.MoveTo(cx+rx, cy)

	// Four quarter-circle arcs
	p.CubicTo(cx+rx, cy+ky, cx+kx, cy+ry, cx, cy+ry)	// to bottom
	p.CubicTo(cx-kx, cy+ry, cx-rx, cy+ky, cx-rx, cy)	// to left
	p.CubicTo(cx-rx, cy-ky, cx-kx, cy-ry, cx, cy-ry)	// to top
	p.CubicTo(cx+kx, cy-ry, cx+rx, cy-ky, cx+rx, cy)	// to right (start)

	return p.Close()
}

func (pp *PathPool) Get() *Path {
	if len(pp.paths) > 0 {
		p := pp.paths[len(pp.paths)-1]
		pp.paths = pp.paths[:len(pp.paths)-1]
		p.Reset()
		return p
	}
	return NewPath()
}

func (p *Path) IsEmpty() bool {
	return len(p.verbs) == 0
}

func (p *Path) LineTo(x, y float32) *Path {
	p.verbs = append(p.verbs, LineTo)
	p.points = append(p.points, x, y)
	p.bounds = p.bounds.UnionPoint(x, y)
	p.cursor = [2]float32{x, y}
	return p
}

func (p *Path) MoveTo(x, y float32) *Path {
	p.verbs = append(p.verbs, MoveTo)
	p.points = append(p.points, x, y)
	p.bounds = p.bounds.UnionPoint(x, y)
	p.start = [2]float32{x, y}
	p.cursor = [2]float32{x, y}
	return p
}

