func (s *Scene) SetTransform(t Affine) {
	s.currentTransform = t
	s.version++
}

func (s *Scene) Stroke(style *StrokeStyle, transform Affine, brush Brush, shape Shape) {
	if shape == nil {
		return
	}
	if style == nil {
		style = DefaultStrokeStyle()
	}

	// Combine with current transform
	combinedTransform := s.currentTransform.Multiply(transform)

	// Get the current layer's encoding
	enc := s.currentEncoding()

	// Emit AA state change if needed (delta encoding).
	s.emitAntiAliasIfNeeded(enc)

	// Encode transform if not identity
	if !combinedTransform.IsIdentity() {
		enc.EncodeTransform(combinedTransform)
	}

	// Convert shape to path and encode — use pooled path when possible.
	path := s.shapeToPath(shape)
	if path == nil || path.IsEmpty() {
		return
	}
	s.encodeScenePath(enc, path)
	s.pathPool.Put(path)

	// Encode stroke command
	enc.EncodeStroke(brush, style)

	// Update bounds (expand by stroke width)
	shapeBounds := shape.Bounds()
	halfWidth := style.Width / 2
	shapeBounds.MinX -= halfWidth
	shapeBounds.MinY -= halfWidth
	shapeBounds.MaxX += halfWidth
	shapeBounds.MaxY += halfWidth

	if !combinedTransform.IsIdentity() {
		shapeBounds = transformBounds(shapeBounds, combinedTransform)
	}
	s.bounds = s.bounds.Union(shapeBounds)
	enc.UpdateBounds(shapeBounds)
	enc.RecordCommandBounds(shapeBounds)

	// Update layer bounds
	s.layerStack.Top().UpdateBounds(shapeBounds)

	s.version++
}

func (s *Scene) TaggedBounds() []TaggedBounds {
	return s.encoding.CommandBounds()
}

func (s *Scene) Transform() Affine {
	return s.currentTransform
}

func (s *Scene) TransformDepth() int {
	return len(s.transformStack)
}

func (s *Scene) Translate(x, y float32) {
	s.currentTransform = s.currentTransform.Multiply(TranslateAffine(x, y))
	s.version++
}

func (s *Scene) Version() uint64 {
	return s.version
}

func (sp *ScenePool) Warmup(count int) {
	scenes := make([]*Scene, count)
	for i := 0; i < count; i++ {
		scenes[i] = sp.Get()
	}
	for i := 0; i < count; i++ {
		sp.Put(scenes[i])
	}
}

type Scene struct {
	// encoding is the root encoding that accumulates all commands
	encoding	*Encoding

	// layerStack manages the hierarchy of compositing layers
	layerStack	*LayerStack

	// transformStack holds the transform state stack
	transformStack	[]Affine

	// clipStack holds the clip state stack
	clipStack	*ClipStack

	// version is incremented on each modification for cache invalidation
	version	uint64

	// bounds tracks the cumulative bounding box of all content
	bounds	Rect

	// currentTransform is the current combined transform
	currentTransform	Affine

	// antiAlias controls whether subsequent draws use anti-aliasing.
	// Default: true. State changes are delta-encoded (TagSetAntiAlias emitted
	// only when the value differs from lastEncodedAA).
	antiAlias	bool

	// lastEncodedAA tracks the last AA state emitted into the encoding.
	// Used for dirty tracking to avoid redundant TagSetAntiAlias tags.
	lastEncodedAA	bool

	// imageRegistry maps image handles to indices
	imageRegistry	[]*Image

	// fontRegistry maps FontSourceID → *text.FontSource for TagText resolution.
	// Populated at scene recording time, consumed at render/playback time.
	fontRegistry	map[uint64]*text.FontSource

	// pathPool reuses Path objects to avoid per-shape allocations in Fill/Stroke.
	// Each shape.ToPath() creates a new Path; pooling eliminates this overhead.
	pathPool	PathPool
}

type Image struct {
	// Width is the image width in pixels
	Width	int

	// Height is the image height in pixels
	Height	int

	// Data holds the pixel data (RGBA format)
	// This will be populated during integration phase
	Data	[]byte
}

type ScenePool struct {
	scenes []*Scene
}

func (cs *CompositeShape) AddShape(shape Shape) {
	cs.shapes = append(cs.shapes, shape)
}

func (rp *RegularPolygonShape) Bounds() Rect {
	// For simplicity, use the circumscribed circle bounds
	// More accurate bounds would require computing all vertices
	return Rect{
		MinX:	rp.CX - rp.R,
		MinY:	rp.CY - rp.R,
		MaxX:	rp.CX + rp.R,
		MaxY:	rp.CY + rp.R,
	}
}

func (p *PolygonShape) Bounds() Rect {
	if len(p.points) < 2 {
		return EmptyRect()
	}

	bounds := Rect{
		MinX:	p.points[0],
		MinY:	p.points[1],
		MaxX:	p.points[0],
		MaxY:	p.points[1],
	}

	for i := 2; i < len(p.points); i += 2 {
		bounds = bounds.UnionPoint(p.points[i], p.points[i+1])
	}

	return bounds
}

func (r *RectShape) Bounds() Rect {
	return Rect{
		MinX:	r.X,
		MinY:	r.Y,
		MaxX:	r.X + r.Width,
		MaxY:	r.Y + r.Height,
	}
}

func (l *LineShape) Bounds() Rect {
	return Rect{
		MinX:	min32(l.X1, l.X2),
		MinY:	min32(l.Y1, l.Y2),
		MaxX:	max32(l.X1, l.X2),
		MaxY:	max32(l.Y1, l.Y2),
	}
}

func (a *ArcShape) Bounds() Rect {
	// Conservative: use the full ellipse bounds
	// More accurate bounds would compute arc extrema
	return Rect{
		MinX:	a.CX - a.RX,
		MinY:	a.CY - a.RY,
		MaxX:	a.CX + a.RX,
		MaxY:	a.CY + a.RY,
	}
}

func (p *PieShape) Bounds() Rect {
	// Conservative: use the full circle bounds
	return Rect{
		MinX:	p.CX - p.R,
		MinY:	p.CY - p.R,
		MaxX:	p.CX + p.R,
		MaxY:	p.CY + p.R,
	}
}

func (s *RoundRectShape) Bounds() Rect {
	return s.Rect
}

func (r *RoundedRectShape) Bounds() Rect {
	return Rect{
		MinX:	r.X,
		MinY:	r.Y,
		MaxX:	r.X + r.Width,
		MaxY:	r.Y + r.Height,
	}
}

func (ps *PathShape) Bounds() Rect {
	if ps.path == nil {
		return EmptyRect()
	}
	return ps.path.Bounds()
}

func (ts *TransformShape) Bounds() Rect {
	if ts.shape == nil {
		return EmptyRect()
	}

	b := ts.shape.Bounds()
	if b.IsEmpty() {
		return b
	}

	// Transform all four corners and compute new bounds
	corners := [][2]float32{
		{b.MinX, b.MinY},
		{b.MaxX, b.MinY},
		{b.MaxX, b.MaxY},
		{b.MinX, b.MaxY},
	}

	result := EmptyRect()
	for _, c := range corners {
		x, y := ts.transform.TransformPoint(c[0], c[1])
		result = result.UnionPoint(x, y)
	}

	return result
}

func (s *StarShape) Bounds() Rect {
	// Use outer radius for bounds (conservative)
	return Rect{
		MinX:	s.CX - s.OuterRadius,
		MinY:	s.CY - s.OuterRadius,
		MaxX:	s.CX + s.OuterRadius,
		MaxY:	s.CY + s.OuterRadius,
	}
}

func (c *CircleShape) Bounds() Rect {
	return Rect{
		MinX:	c.CX - c.R,
		MinY:	c.CY - c.R,
		MaxX:	c.CX + c.R,
		MaxY:	c.CY + c.R,
	}
}

func (e *EllipseShape) Bounds() Rect {
	return Rect{
		MinX:	e.CX - e.RX,
		MinY:	e.CY - e.RY,
		MaxX:	e.CX + e.RX,
		MaxY:	e.CY + e.RY,
	}
}

func (cs *CompositeShape) Bounds() Rect {
	result := EmptyRect()
	for _, shape := range cs.shapes {
		if shape != nil {
			result = result.Union(shape.Bounds())
		}
	}
	return result
}

func (e *EllipseShape) BuildPathInto(p *Path) {
	p.Reset()
	p.Ellipse(e.CX, e.CY, e.RX, e.RY)
}

func (r *RectShape) BuildPathInto(p *Path) {
	p.Reset()
	p.Rectangle(r.X, r.Y, r.Width, r.Height)
}

func (c *CircleShape) BuildPathInto(p *Path) {
	p.Reset()
	p.Circle(c.CX, c.CY, c.R)
}

func (r *RoundedRectShape) BuildPathInto(p *Path) {
	p.Reset()
	p.RoundedRectangle(r.X, r.Y, r.Width, r.Height, r.Radius)
}

func (p *PolygonShape) BuildPathInto(dst *Path) {
	dst.Reset()
	if len(p.points) < 4 {
		return
	}
	dst.MoveTo(p.points[0], p.points[1])
	for i := 2; i < len(p.points); i += 2 {
		dst.LineTo(p.points[i], p.points[i+1])
	}
	dst.Close()
}

func (l *LineShape) BuildPathInto(p *Path) {
	p.Reset()
	p.MoveTo(l.X1, l.Y1)
	p.LineTo(l.X2, l.Y2)
}

func (r *RectShape) Contains(px, py float32) bool {
	return px >= r.X && px <= r.X+r.Width &&
		py >= r.Y && py <= r.Y+r.Height
}

func (e *EllipseShape) Contains(px, py float32) bool {
	if e.RX == 0 || e.RY == 0 {
		return false
	}
	dx := (px - e.CX) / e.RX
	dy := (py - e.CY) / e.RY
	return dx*dx+dy*dy <= 1
}

func (c *CircleShape) Contains(px, py float32) bool {
	dx := px - c.CX
	dy := py - c.CY
	return dx*dx+dy*dy <= c.R*c.R
}

func (s *RoundRectShape) Contains(px, py float32) bool {
	// Quick AABB reject
	if px < s.Rect.MinX || px > s.Rect.MaxX || py < s.Rect.MinY || py > s.Rect.MaxY {
		return false
	}

	cx := (s.Rect.MinX + s.Rect.MaxX) / 2
	cy := (s.Rect.MinY + s.Rect.MaxY) / 2
	halfW := s.Rect.Width() / 2
	halfH := s.Rect.Height() / 2
	r := min32(s.RadiusX, s.RadiusY)

	dist := sdfRoundRect(px, py, cx, cy, halfW, halfH, r)
	return dist <= 0
}

func (l *LineShape) Length() float32 {
	dx := l.X2 - l.X1
	dy := l.Y2 - l.Y1
	return float32(math.Sqrt(float64(dx*dx + dy*dy)))
}

