	// Advance is the distance to the next glyph position.
	Advance	float32

	// Position is the glyph position relative to the text origin.
	X, Y	float32

	// GID is the glyph ID.
	GID	text.GlyphID

	// Type indicates the glyph type.
	Type	text.GlyphType

	// Cluster is the source character index.
	Cluster	int
