		height:		height,
		img:		image.NewRGBA(image.Rect(0, 0, width, height)),
		filler:		raster.NewAnalyticFiller(width, height),
		edgeBuilder:	raster.NewEdgeBuilder(2),	// 4x AA quality
	}
}

