func (c *Context) StrokeString(s string, x, y float64) {
	if c.face == nil {
		return
	}
	path := c.textOutlinePath(s, x, y)
	if path == nil {
		return
	}

	devicePath := path.Transform(c.totalMatrix())
	c.trackDamage(devicePath.Bounds())

	// Set GPU scissor rect for rectangular clips.
	defer c.setGPUClipRect()()

	// Save and restore context path — doStroke uses c.path.
	savedPath := c.path
	c.path = devicePath
	_ = c.doStroke()
	c.path = savedPath
}

func (c *Context) StrokeStringAnchored(s string, x, y, ax, ay float64) {
	if c.face == nil {
		return
	}

	w, _ := text.Measure(s, c.face)
	metrics := c.face.Metrics()
	h := metrics.Ascent + metrics.Descent
	x -= w * ax
	y = y + metrics.Ascent - ay*h

	c.StrokeString(s, x, y)
}

func (c *Context) TextPath(s string, x, y float64) *Path {
	if c.face == nil {
		return nil
	}
	return c.textOutlinePath(s, x, y)
}

func (c *Context) WordWrap(s string, w float64) []string {
	if c.face == nil {
		return []string{s}
	}
	results := text.WrapText(s, c.face, w, text.WrapWord)
	lines := make([]string, len(results))
	for i, r := range results {
		lines[i] = r.Text
	}
	return lines
}

func (c *Cache[K, V]) Clear() {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.entries = make(map[K]*cacheEntry[V])
	c.tick = 0
}

func (c *Cache[K, V]) Get(key K) (V, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	entry, ok := c.entries[key]
	if !ok {
		var zero V
		return zero, false
	}

	// Update access time
	c.tick++
	entry.atime = c.tick

	return entry.value, true
}

func (c *Cache[K, V]) GetOrCreate(key K, create func() V) V {
	c.mu.Lock()
	defer c.mu.Unlock()

	// Check if already in cache
	if entry, ok := c.entries[key]; ok {
		// Update access time
		c.tick++
		entry.atime = c.tick
		return entry.value
	}

	// Create new value (under lock)
	value := create()

	// Store in cache
	c.tick++
	c.entries[key] = &cacheEntry[V]{
		value:	value,
		atime:	c.tick,
	}

	// Evict if over soft limit
	if c.softLimit > 0 && len(c.entries) > c.softLimit {
		c.evictOldest()
	}

	return value
}

func (c *Cache[K, V]) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()

	return len(c.entries)
}

func NewCache[K comparable, V any](softLimit int) *Cache[K, V] {
	return &Cache[K, V]{
		entries:	make(map[K]*cacheEntry[V]),
		softLimit:	softLimit,
		tick:		0,
	}
}

func (c *Cache[K, V]) Set(key K, value V) {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.tick++
	c.entries[key] = &cacheEntry[V]{
		value:	value,
		atime:	c.tick,
	}

	// Evict if over soft limit
	if c.softLimit > 0 && len(c.entries) > c.softLimit {
		c.evictOldest()
	}
}

type Cache[K comparable, V any] struct {
	mu		sync.Mutex
	entries		map[K]*cacheEntry[V]
	softLimit	int
	tick		int64	// Monotonic access counter
}

type ShapingKey struct {
	Text		string
	Size		float64
	Direction	Direction
}

type GlyphKey struct {
	GID	GlyphID
