func IsBlackFlag(r rune) bool {
	return r == 0x1F3F4
}

func IsCancelTag(r rune) bool {
	return r == 0xE007F
}

func IsCombiningEnclosingKeycap(r rune) bool {
	return r == 0x20E3
}

func IsEmoji(r rune) bool {
	return isEmojiPresentation(r) || isEmojiComponent(r) || isTextPresentationEmoji(r)
}

func IsEmojiModifier(r rune) bool {
	return r >= 0x1F3FB && r <= 0x1F3FF
}

func IsEmojiPresentation(r rune) bool {
	return isEmojiPresentation(r)
}

func IsEmojiVariation(r rune) bool {
	return r == 0xFE0F
}

func IsKeycapBase(r rune) bool {
	return (r >= '0' && r <= '9') || r == '#' || r == '*'
}

func IsRegionalIndicator(r rune) bool {
	return r >= 0x1F1E6 && r <= 0x1F1FF
}

func IsTagCharacter(r rune) bool {
	return r >= 0xE0020 && r <= 0xE007E
}

func IsTextPresentation(r rune) bool {
	return r == 0xFE0E
}

func IsVariationSelector(r rune) bool {
	return r == 0xFE0E || r == 0xFE0F
}

func IsZWJ(r rune) bool {
	return r == 0x200D
}

func Segment(text string) []Run {
	if text == "" {
		return nil
	}

	runes := []rune(text)
	if len(runes) == 0 {
		return nil
	}

	runs := make([]Run, 0, 4)
	byteOffsets := computeByteOffsets(text, runes)

	i := 0
	for i < len(runes) {
		// Try to parse a complete emoji sequence
		emojiLen, codepoints := parseEmojiSequence(runes[i:])

		if emojiLen > 0 {
			// Found an emoji sequence
			run := Run{
				Text:		text[byteOffsets[i]:byteOffsets[i+emojiLen]],
				IsEmoji:	true,
				Codepoints:	codepoints,
				Start:		byteOffsets[i],
				End:		byteOffsets[i+emojiLen],
			}
			runs = appendOrMergeRun(runs, run)
			i += emojiLen
		} else {
			// Regular text character
			run := Run{
				Text:		text[byteOffsets[i]:byteOffsets[i+1]],
				IsEmoji:	false,
				Start:		byteOffsets[i],
				End:		byteOffsets[i+1],
			}
			runs = appendOrMergeRun(runs, run)
			i++
		}
	}

	return runs
}

type Run struct {
	// Text is the substring of the run.
	Text	string

	// IsEmoji is true if this run contains emoji characters.
	// For ZWJ sequences, this will be a single Run with multiple codepoints.
	IsEmoji	bool

	// Codepoints contains the individual runes for emoji runs.
	// For non-emoji runs, this is nil.
	Codepoints	[]rune

	// Start is the byte offset in the original string.
	Start	int

	// End is the byte offset of the end (exclusive).
	End	int
}

func GetFlagCode(seq Sequence) string {
	if seq.Type != SequenceFlag || len(seq.Codepoints) != 2 {
		return ""
	}

	a := seq.Codepoints[0]
	b := seq.Codepoints[1]

	if !IsRegionalIndicator(a) || !IsRegionalIndicator(b) {
		return ""
	}

	// Regional indicators A-Z map to U+1F1E6-U+1F1FF
	// Convert to ASCII letters
	letterA := 'A' + (a - 0x1F1E6)
	letterB := 'A' + (b - 0x1F1E6)

	return string([]rune{letterA, letterB})
}

func GetTagSequenceCode(seq Sequence) string {
	if seq.Type != SequenceTag || len(seq.Codepoints) < 3 {
		return ""
	}

	// Skip black flag and cancel tag, extract middle tag characters
	code := make([]rune, 0, len(seq.Codepoints)-2)
	for i := 1; i < len(seq.Codepoints)-1; i++ {
		r := seq.Codepoints[i]
		if !IsTagCharacter(r) {
			return ""
		}
		// Convert tag character to ASCII (E0020-E007E -> 0020-007E)
		code = append(code, r-0xE0000)
	}

	return string(code)
}

func (s Sequence) HasModifier() bool {
	return s.Modifier != 0
}

func IsValidSequence(seq Sequence) bool {
	if len(seq.Codepoints) == 0 {
		return false
	}

	switch seq.Type {
	case SequenceSimple:
		return len(seq.Codepoints) == 1 && IsEmoji(seq.Codepoints[0])

	case SequenceFlag:
		return len(seq.Codepoints) == 2 &&
			IsRegionalIndicator(seq.Codepoints[0]) &&
			IsRegionalIndicator(seq.Codepoints[1])

	case SequenceKeycap:
		if len(seq.Codepoints) < 2 || len(seq.Codepoints) > 3 {
			return false
		}
		if !IsKeycapBase(seq.Codepoints[0]) {
			return false
		}
		last := seq.Codepoints[len(seq.Codepoints)-1]
		return IsCombiningEnclosingKeycap(last)

	case SequenceTag:
		if len(seq.Codepoints) < 3 {
			return false
		}
		if !IsBlackFlag(seq.Codepoints[0]) {
			return false
		}
		if !IsCancelTag(seq.Codepoints[len(seq.Codepoints)-1]) {
			return false
		}
		// All middle characters must be tags
		for i := 1; i < len(seq.Codepoints)-1; i++ {
			if !IsTagCharacter(seq.Codepoints[i]) {
				return false
			}
		}
		return true

	case SequenceModified:
		if len(seq.Codepoints) < 2 {
			return false
		}
		if !IsEmojiModifierBase(seq.Codepoints[0]) {
			return false
		}
		return seq.HasModifier()

	case SequenceZWJ:
		// Must contain at least one ZWJ
		hasZWJ := false
		for _, r := range seq.Codepoints {
			if IsZWJ(r) {
				hasZWJ = true
				break
			}
		}
		return hasZWJ

	case SequencePresentation:
		// Must have variation selector
		hasVS := false
		for _, r := range seq.Codepoints {
			if IsVariationSelector(r) {
				hasVS = true
				break
			}
		}
		return hasVS

	default:
		return false
	}
}

func (s Sequence) Len() int {
	return len(s.Codepoints)
}

func Normalize(seq Sequence) Sequence {
	if len(seq.Codepoints) == 0 {
		return seq
	}

	normalized := make([]rune, 0, len(seq.Codepoints))
	prevBase := rune(0)

	for _, r := range seq.Codepoints {
		// Skip text variation selector
		if IsTextPresentation(r) {
			continue
		}

		// Skip emoji variation selector (we'll add it back if needed)
		if IsEmojiVariation(r) {
			// Add FE0F for text-presentation emoji that need it
			if isTextPresentationEmoji(prevBase) {
				normalized = append(normalized, r)
			}
			continue
		}

		// Skip invalid modifiers
		if IsEmojiModifier(r) {
			if !IsEmojiModifierBase(prevBase) {
				continue
			}
		}

		normalized = append(normalized, r)
		if !IsZWJ(r) && !IsEmojiModifier(r) && !IsVariationSelector(r) {
			prevBase = r
		}
	}

	return Sequence{
		Codepoints:	normalized,
		Type:		seq.Type,
		BaseCodepoint:	seq.BaseCodepoint,
		Modifier:	seq.Modifier,
	}
}

func Parse(runes []rune) []Sequence {
	if len(runes) == 0 {
		return nil
	}

	sequences := make([]Sequence, 0, len(runes))
	i := 0

	for i < len(runes) {
		seq, consumed := parseSequenceAt(runes[i:])
		if consumed > 0 {
			sequences = append(sequences, seq)
			i += consumed
		} else {
			// Skip non-emoji character
			i++
		}
	}

	return sequences
}

func ParseString(text string) []Sequence {
	return Parse([]rune(text))
}

