func (f *sourceFace) Advance(text string) float64 {
	parsed := f.source.Parsed()
	totalAdvance := 0.0

	for _, r := range text {
		if r < 0x20 && r != '\t' {
			continue
		}
		var advance float64
		if r == '\t' {
			_, advance = tabAdvance(parsed, f.size)
		} else {
			gid := parsed.GlyphIndex(r)
			advance = parsed.GlyphAdvance(gid, f.size)
		}
		totalAdvance += advance
	}

	return totalAdvance
}

func (f *sourceFace) AppendGlyphs(dst []Glyph, text string) []Glyph {
	parsed := f.source.Parsed()
	x := 0.0
	byteIndex := 0

	for i, r := range text {
		// Skip non-tab control characters.
		if r < 0x20 && r != '\t' {
			byteIndex += utf8.RuneLen(r)
			continue
		}

		var gid uint16
		var advance float64
		var bounds Rect

		if r == '\t' {
			gid, advance = tabAdvance(parsed, f.size)
		} else {
			gid = parsed.GlyphIndex(r)
			advance = parsed.GlyphAdvance(gid, f.size)
			bounds = parsed.GlyphBounds(gid, f.size)
		}

		glyph := Glyph{
			Rune:		r,
			GID:		GlyphID(gid),
			X:		x,
			Y:		0,
			OriginX:	x,
			OriginY:	0,
			Advance:	advance,
			Bounds:		bounds,
			Index:		byteIndex,
			Cluster:	i,
		}

		dst = append(dst, glyph)
		x += advance
		byteIndex += utf8.RuneLen(r)
	}

	return dst
}

func (f *sourceFace) Direction() Direction {
	return f.config.direction
}

func (f *sourceFace) Glyphs(text string) iter.Seq[Glyph] {
	return func(yield func(Glyph) bool) {
		parsed := f.source.Parsed()
		x := 0.0
		byteIndex := 0

		for i, r := range text {
			// Skip non-tab control characters.
			if r < 0x20 && r != '\t' {
				byteIndex += utf8.RuneLen(r)
				continue
			}

			var gid uint16
			var advance float64
			var bounds Rect

			if r == '\t' {
				// Tab: use space GID (empty outline) with tab-stop advance.
				gid, advance = tabAdvance(parsed, f.size)
				// Space bounds are empty — no visual rendering.
			} else {
				gid = parsed.GlyphIndex(r)
				advance = parsed.GlyphAdvance(gid, f.size)
				bounds = parsed.GlyphBounds(gid, f.size)
			}

			glyph := Glyph{
				Rune:		r,
				GID:		GlyphID(gid),
				X:		x,
				Y:		0,
				OriginX:	x,
				OriginY:	0,
				Advance:	advance,
				Bounds:		bounds,
				Index:		byteIndex,
				Cluster:	i,
			}

			if !yield(glyph) {
				return
			}

			x += advance
			byteIndex += utf8.RuneLen(r)
		}
	}
}

func (f *sourceFace) HasGlyph(r rune) bool {
	parsed := f.source.Parsed()
	gid := parsed.GlyphIndex(r)
	return gid != 0
}

func (f *sourceFace) Metrics() Metrics {
	parsed := f.source.Parsed()
	fontMetrics := parsed.Metrics(f.size)

	// FontMetrics.Descent is negative (below baseline)
	// Metrics.Descent is positive (absolute distance from baseline)
	descent := fontMetrics.Descent
	if descent < 0 {
		descent = -descent
	}

	return Metrics{
		Ascent:		fontMetrics.Ascent,
		Descent:	descent,
		LineGap:	fontMetrics.LineGap,
		XHeight:	fontMetrics.XHeight,
		CapHeight:	fontMetrics.CapHeight,
	}
}

func (f *sourceFace) Size() float64 {
	return f.size
}

func (f *sourceFace) Source() *FontSource {
	return f.source
}

type Face interface {
	// Metrics returns the font metrics at this face's size.
	Metrics() Metrics

	// Advance returns the total advance width of the text in pixels.
	// This is the sum of all glyph advances.
	Advance(text string) float64

	// HasGlyph reports whether the font has a glyph for the given rune.
	HasGlyph(r rune) bool

	// Glyphs returns an iterator over all glyphs in the text.
	// The glyphs are positioned relative to the origin (0, 0).
	// Uses Go 1.25+ iter.Seq for zero-allocation iteration.
	Glyphs(text string) iter.Seq[Glyph]

	// AppendGlyphs appends glyphs for the text to dst and returns the extended slice.
	// This is useful for building glyph slices without allocation.
	AppendGlyphs(dst []Glyph, text string) []Glyph

	// Direction returns the text direction for this face.
	Direction() Direction

	// Source returns the FontSource this face was created from.
	Source() *FontSource

	// Size returns the size of this face in points.
	Size() float64

	// private prevents external implementation
	private()
}

func (f *FilteredFace) Advance(text string) float64 {
	totalAdvance := 0.0

	for _, r := range text {
		if f.inRanges(r) {
			// Get glyph advance from the wrapped face
			glyphAdvance := 0.0
			for glyph := range f.face.Glyphs(string(r)) {
				glyphAdvance = glyph.Advance
				break	// Only one glyph for a single rune
			}
			totalAdvance += glyphAdvance
		}
	}

	return totalAdvance
}

func (f *FilteredFace) AppendGlyphs(dst []Glyph, text string) []Glyph {
	for glyph := range f.Glyphs(text) {
		dst = append(dst, glyph)
	}
	return dst
}

func (ur UnicodeRange) Contains(r rune) bool {
	return r >= ur.Start && r <= ur.End
}

func (f *FilteredFace) Direction() Direction {
	return f.face.Direction()
}

func (f *FilteredFace) Glyphs(text string) iter.Seq[Glyph] {
	return func(yield func(Glyph) bool) {
		for glyph := range f.face.Glyphs(text) {
			if f.inRanges(glyph.Rune) {
				if !yield(glyph) {
					return
				}
			}
		}
	}
}

func (f *FilteredFace) HasGlyph(r rune) bool {
	if !f.inRanges(r) {
		return false
	}
	return f.face.HasGlyph(r)
}

func (f *FilteredFace) Metrics() Metrics {
	return f.face.Metrics()
}

func NewFilteredFace(face Face, ranges ...UnicodeRange) *FilteredFace {
	return &FilteredFace{
		face:	face,
		ranges:	ranges,
	}
}

func (f *FilteredFace) Size() float64 {
	return f.face.Size()
}

func (f *FilteredFace) Source() *FontSource {
	return f.face.Source()
}

type UnicodeRange struct {
	Start	rune
	End	rune
}

type FilteredFace struct {
	face	Face
	ranges	[]UnicodeRange
}

type Glyph struct {
	// Rune is the Unicode character this glyph represents.
	// For ligatures, this may be the first character of the ligature.
	Rune	rune

	// GID is the glyph index in the font.
	GID	GlyphID

	// X, Y are the position of the glyph relative to the text origin.
	// The origin is at the baseline of the first character.
	X, Y	float64

	// OriginX, OriginY are the absolute position of the glyph's origin point.
	// This is where the glyph should be drawn from.
	OriginX	float64
	OriginY	float64

	// Advance is the horizontal advance width of the glyph.
	// This is how much the cursor moves after drawing this glyph.
	Advance	float64

	// Bounds is the bounding box of the glyph.
	// This defines the area the glyph occupies.
	Bounds	Rect

	// Index is the byte position in the original string where this glyph starts.
	Index	int

	// Cluster is the character cluster index.
	// Multiple glyphs can belong to the same cluster (e.g., ligatures).
	Cluster	int
}

func (c *GlyphCache) Clear() {
	for i := 0; i < numShards; i++ {
		shard := c.shards[i]
		shard.mu.Lock()
		shard.entries = make(map[OutlineCacheKey]*glyphEntry, shard.maxEntries)
		shard.head = nil
		shard.tail = nil
		shard.count = 0
		shard.mu.Unlock()
	}
}

func (c *GlyphCache) CurrentFrame() uint64 {
	return c.currentFrame.Load()
}

func DefaultGlyphCacheConfig() GlyphCacheConfig {
	return GlyphCacheConfig{
		MaxEntries:	4096,
		FrameLifetime:	64,
	}
}

func (c *GlyphCache) Delete(key OutlineCacheKey) {
	shard := c.getShard(key)

	shard.mu.Lock()
	defer shard.mu.Unlock()

	entry, ok := shard.entries[key]
	if !ok {
		return
	}

	shard.remove(entry)
	delete(shard.entries, key)
	shard.count--
}

func (p *GlyphCachePool) Get() *GlyphCache {
	return p.pool.Get().(*GlyphCache)
}

func GetGlobalGlyphCache() *GlyphCache {
	return globalGlyphCache
}

func (c *GlyphCache) GetOrCreate(key OutlineCacheKey, create func() *GlyphOutline) *GlyphOutline {
	// First try a fast read-only lookup
	shard := c.getShard(key)
	frame := c.currentFrame.Load()

	shard.mu.RLock()
	if _, ok := shard.entries[key]; ok {
		shard.mu.RUnlock()
		// Upgrade to write lock to update access time
		shard.mu.Lock()
		if entry, ok := shard.entries[key]; ok {
			entry.lastAccessFrame = frame
			shard.moveToFront(entry)
			outline := entry.outline
			shard.mu.Unlock()
			c.stats.Hits.Add(1)
			return outline
		}
		shard.mu.Unlock()
	} else {
		shard.mu.RUnlock()
	}

	// Need to create
	if create == nil {
		c.stats.Misses.Add(1)
		return nil
	}

	outline := create()
	if outline != nil {
		c.Set(key, outline)
	} else {
		c.stats.Misses.Add(1)
	}
	return outline
}

func (c *GlyphCache) HitRate() float64 {
	hits := c.stats.Hits.Load()
	misses := c.stats.Misses.Load()
	total := hits + misses
	if total == 0 {
		return 0
	}
	return float64(hits) / float64(total) * 100
}

func (c *GlyphCache) Len() int {
	total := 0
	for i := 0; i < numShards; i++ {
		shard := c.shards[i]
		shard.mu.RLock()
		total += shard.count
		shard.mu.RUnlock()
	}
	return total
}

func (c *GlyphCache) Maintain() {
	frame := c.currentFrame.Add(1)
	// FrameLifetime is validated to be positive in NewGlyphCacheWithConfig
	frameLifetime := max(c.config.FrameLifetime, 1)

	// Avoid underflow when frame < FrameLifetime
	// frameLifetime is guaranteed >= 1 so conversion is safe
	frameLifetimeU64 := uint64(frameLifetime)	//nolint:gosec // validated >= 1 above
	if frame < frameLifetimeU64 {
		return
	}
	threshold := frame - frameLifetimeU64

	for i := 0; i < numShards; i++ {
		shard := c.shards[i]
		shard.mu.Lock()

		// Walk from tail (oldest) and evict stale entries
		entry := shard.tail
		for entry != nil && entry.lastAccessFrame < threshold {
			prev := entry.prev
			delete(shard.entries, entry.key)
			shard.remove(entry)
			shard.count--
			c.stats.Evictions.Add(1)
			entry = prev
		}

		shard.mu.Unlock()
	}
}

func NewGlyphCache() *GlyphCache {
	return NewGlyphCacheWithConfig(DefaultGlyphCacheConfig())
}

func NewGlyphCachePool() *GlyphCachePool {
	return &GlyphCachePool{
		pool: sync.Pool{
			New: func() any {
				return NewGlyphCache()
			},
		},
	}
}

func NewGlyphCacheWithConfig(config GlyphCacheConfig) *GlyphCache {
	if config.MaxEntries <= 0 {
		config.MaxEntries = 4096
	}
	if config.FrameLifetime <= 0 {
		config.FrameLifetime = 64
	}

	c := &GlyphCache{
		config: config,
	}

	// Divide entries among shards
	entriesPerShard := (config.MaxEntries + numShards - 1) / numShards

	for i := 0; i < numShards; i++ {
		c.shards[i] = &glyphShard{
			entries:	make(map[OutlineCacheKey]*glyphEntry, entriesPerShard),
			maxEntries:	entriesPerShard,
		}
	}

	return c
}

func (p *GlyphCachePool) Put(c *GlyphCache) {
	if c != nil {
		c.Clear()
		p.pool.Put(c)
	}
}

func (c *GlyphCache) ResetStats() {
	c.stats.Hits.Store(0)
	c.stats.Misses.Store(0)
	c.stats.Evictions.Store(0)
	c.stats.Insertions.Store(0)
}

func (c *GlyphCache) Set(key OutlineCacheKey, outline *GlyphOutline) {
	if outline == nil {
		return
	}

	shard := c.getShard(key)
	frame := c.currentFrame.Load()

	shard.mu.Lock()
	defer shard.mu.Unlock()

	// Check if already exists
	if existing, ok := shard.entries[key]; ok {
		existing.outline = outline
		existing.lastAccessFrame = frame
		shard.moveToFront(existing)
		return
	}

	// Create new entry
	entry := &glyphEntry{
		key:			key,
		outline:		outline,
		lastAccessFrame:	frame,
	}

	// Evict if necessary
	for shard.count >= shard.maxEntries && shard.tail != nil {
		shard.removeTail()
		c.stats.Evictions.Add(1)
	}

	// Add to cache
	shard.entries[key] = entry
	shard.addToFront(entry)
	shard.count++
	c.stats.Insertions.Add(1)
}

func SetGlobalGlyphCache(cache *GlyphCache) *GlyphCache {
	if cache == nil {
		cache = NewGlyphCache()
	}
	old := globalGlyphCache
	globalGlyphCache = cache
	return old
}

func (c *GlyphCache) Stats() (hits, misses, evictions, insertions uint64) {
	return c.stats.Hits.Load(),
		c.stats.Misses.Load(),
		c.stats.Evictions.Load(),
		c.stats.Insertions.Load()
}

