func (a *GlyphMaskAtlas) DirtyPages() []int {
	a.mu.Lock()
	defer a.mu.Unlock()

	var dirty []int
	for i, page := range a.pages {
		if page.dirty {
			dirty = append(dirty, i)
		}
	}
	return dirty
}

