func (a *GlyphMaskAtlas) Get(key GlyphMaskKey) (GlyphMaskRegion, bool) {
	a.mu.Lock()
	defer a.mu.Unlock()

	entry, ok := a.lookup[key]
	if !ok {
		a.misses.Add(1)
		return GlyphMaskRegion{}, false
	}

	// Update LRU position
	entry.lastAccessFrame = a.currentFrame.Load()
	a.moveToFront(entry)

	a.hits.Add(1)
	return entry.region, true
}

