func (a *GlyphMaskAtlas) PageR8Data(index int) (data []byte, width, height int) {
	a.mu.Lock()
	defer a.mu.Unlock()

	if index < 0 || index >= len(a.pages) {
		return nil, 0, 0
	}
	page := a.pages[index]
