func (o *GlyphOutline) Clone() *GlyphOutline {
	if o == nil {
		return nil
	}

	clone := &GlyphOutline{
		Segments:	make([]OutlineSegment, len(o.Segments)),
		Bounds:		o.Bounds,
		Advance:	o.Advance,
		LSB:		o.LSB,
		GID:		o.GID,
		Type:		o.Type,
	}
	copy(clone.Segments, o.Segments)
	return clone
}

