	font := run.Face.Source().Parsed()
	if font == nil {
		return
	}

	fontID := computeFontID(font)
	size := float32(run.Size)

	for i := range run.Glyphs {
		glyph := &run.Glyphs[i]
		pos := Point{
			X:	origin.X + float32(glyph.X),
			Y:	origin.Y + float32(glyph.Y),
