func (f GlyphFlags) String() string {
	if f == 0 {
		return noneStr
	}

	var result string
	if f.Has(GlyphFlagLigature) {
		result += "Ligature|"
	}
	if f.Has(GlyphFlagMark) {
		result += "Mark|"
	}
	if f.Has(GlyphFlagSafeToBreak) {
		result += "SafeToBreak|"
	}
	if f.Has(GlyphFlagClusterStart) {
		result += "ClusterStart|"
	}

	// Remove trailing pipe
	if result != "" {
		result = result[:len(result)-1]
	}
	return result
}

