func LayoutTextWithContext(ctx context.Context, text string, face Face, opts LayoutOptions) (*Layout, error) {
	if text == "" {
		return &Layout{}, nil
	}
	if face == nil {
		return &Layout{}, nil
	}

	// Check for cancellation at start
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	// Apply defaults for zero values
	if opts.LineSpacing <= 0 {
		opts.LineSpacing = 1.0
	}

	// Get font metrics for line height calculation
	metrics := face.Metrics()

	// Split by hard line breaks
	paragraphs := splitParagraphs(text)

	layout := &Layout{
		Lines: make([]Line, 0, len(paragraphs)),
	}

	var y float64

	for i, para := range paragraphs {
		// Check for cancellation periodically (every 8 paragraphs)
		if i%8 == 0 && i > 0 {
			select {
			case <-ctx.Done():
				return nil, ctx.Err()
			default:
			}
		}

		paraLines := layoutParagraph(para, face, opts, metrics)

		for j := range paraLines {
			line := &paraLines[j]

			// Calculate baseline position: previous Y + line ascent
			if len(layout.Lines) == 0 && j == 0 {
				// Very first line of entire layout
				y = line.Ascent
			} else {
				// Get previous line: from current paragraph or from layout.Lines
				var prevLine *Line
				if j > 0 {
					prevLine = &paraLines[j-1]
				} else {
					prevLine = &layout.Lines[len(layout.Lines)-1]
				}
				lineGap := metrics.LineGap * opts.LineSpacing
				y = prevLine.Y + prevLine.Descent + lineGap + line.Ascent
			}

			line.Y = y

			// Apply horizontal alignment
			applyAlignment(line, opts.Alignment, opts.MaxWidth)

			// Track layout bounds
			if line.Width > layout.Width {
				layout.Width = line.Width
			}
		}

		layout.Lines = append(layout.Lines, paraLines...)
	}

	// Calculate total height
	if len(layout.Lines) > 0 {
		lastLine := &layout.Lines[len(layout.Lines)-1]
		layout.Height = lastLine.Y + lastLine.Descent
	}

	return layout, nil
}

type LayoutOptions struct {
	// MaxWidth is the maximum line width in pixels.
	// If 0, no line wrapping is performed (single-line paragraphs).
	MaxWidth	float64

	// LineSpacing is a multiplier for line height.
	// 1.0 uses the font's natural line height; 1.5 adds 50% extra space.
	LineSpacing	float64

	// Alignment specifies horizontal text alignment.
	Alignment	Alignment

	// Direction is the base text direction (LTR or RTL).
	// Used for paragraph-level direction when no strong directional text is present.
	Direction	Direction

	// WrapMode specifies how text is wrapped when it exceeds MaxWidth.
	// Default is WrapWordChar which breaks at word boundaries first,
	// then falls back to character boundaries for long words.
	WrapMode	WrapMode
}

type Line struct {
	// Runs contains the shaped runs that make up this line.
	// Multiple runs occur with mixed scripts or directions.
	Runs	[]ShapedRun

	// Glyphs contains all glyphs from Runs, positioned for rendering.
	// Glyph X positions are absolute within the layout.
	Glyphs	[]ShapedGlyph

	// Width is the total advance width of all glyphs in this line.
	Width	float64

	// Ascent is the maximum ascent of all runs (distance above baseline).
	Ascent	float64

	// Descent is the maximum descent of all runs (distance below baseline).
	Descent	float64

	// Y is the baseline Y position of this line within the layout.
	Y	float64
}

type Layout struct {
	// Lines contains all lines of laid out text.
	Lines	[]Line

	// Width is the maximum width among all lines.
	Width	float64

	// Height is the total height of all lines.
	Height	float64
}

func (f *LCDFilter) Apply(dst []byte, src []byte, width int) {
	srcLen := 3 * width
	if len(dst) < width*3 || len(src) < srcLen {
		return
	}

	for i := range width {
		// For each output pixel, filter 3 subpixel columns independently.
		for ch := range 3 {
			center := i*3 + ch	// index in the 3x-wide source buffer

			var acc float32
			for tap := range 5 {
				srcIdx := center + tap - 2	// 5-tap centered: -2, -1, 0, +1, +2
				if srcIdx >= 0 && srcIdx < srcLen {
					acc += f.Weights[tap] * float32(src[srcIdx])
				}
			}

			// Clamp to [0, 255]
			v := int(acc + 0.5)
			if v < 0 {
				v = 0
			}
			if v > 255 {
				v = 255
			}
			dst[i*3+ch] = byte(v)	//nolint:gosec // v is clamped to [0,255]
		}
	}
}

func DefaultLCDFilter() LCDFilter {
	return LCDFilter{Weights: [5]float32{0.08, 0.24, 0.36, 0.24, 0.08}}
}

func (l LCDLayout) String() string {
	switch l {
	case LCDLayoutNone:
		return noneStr
	case LCDLayoutRGB:
		return "RGB"
	case LCDLayoutBGR:
		return "BGR"
	default:
		return unknownStr
	}
}

type LCDFilter struct {
	// Weights are the 5-tap FIR filter coefficients, centered on the
	// current subpixel column. Weights[2] is the center tap.
	Weights [5]float32
}

type LCDMaskResult struct {
	// Mask is the RGB coverage buffer (3 bytes per pixel: R, G, B).
	// Row-major, width x height pixels, 3*width bytes per row.
	Mask	[]byte

	// Width and Height of the mask in pixels (NOT the 3x oversampled width).
	Width, Height	int

	// BearingX is the horizontal offset from the glyph origin to the left
	// edge of the mask bounding box, in pixels.
	BearingX	float32

	// BearingY is the vertical offset from the baseline to the top edge
	// of the mask bounding box, in pixels. Positive = above baseline.
	BearingY	float32
}

func (m Metrics) LineHeight() float64 {
	return m.Ascent + m.Descent + m.LineGap
}

type Metrics struct {
	// Ascent is the distance from the baseline to the top of the font (positive).
	// This is the maximum height a glyph can reach above the baseline.
	Ascent	float64

	// Descent is the distance from the baseline to the bottom of the font (positive, below baseline).
	// This is the maximum depth a glyph can reach below the baseline.
	// Note: Unlike FontMetrics.Descent, this is stored as a positive value.
	Descent	float64

	// LineGap is the recommended gap between lines.
	LineGap	float64

	// XHeight is the height of lowercase letters (like 'x').
	XHeight	float64

	// CapHeight is the height of uppercase letters.
	CapHeight	float64
}

func (m *AtlasManager) AtlasCount() int {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return len(m.atlases)
}

func (m *AtlasManager) AtlasInfos() []AtlasInfo {
	m.mu.RLock()
	defer m.mu.RUnlock()

	infos := make([]AtlasInfo, len(m.atlases))
	for i, atlas := range m.atlases {
		infos[i] = AtlasInfo{
			Index:		i,
			GlyphCount:	len(atlas.regions),
			Utilization:	atlas.Utilization(),
			Dirty:		atlas.dirty,
			MemoryBytes:	len(atlas.Data),
		}
	}
	return infos
}

func (c *ConcurrentAtlasManager) Clear() {
	for _, shard := range c.shards {
		shard.Clear()
	}
}

func (m *AtlasManager) Compact() int {
	m.mu.Lock()
	defer m.mu.Unlock()

	removed := 0
	newAtlases := make([]*Atlas, 0, len(m.atlases))

	for _, atlas := range m.atlases {
		if len(atlas.regions) > 0 {
			atlas.index = len(newAtlases)
			// Update region atlas indices
			for key, region := range atlas.regions {
				region.AtlasIndex = atlas.index
				atlas.regions[key] = region
				m.lookup[key] = region
			}
			newAtlases = append(newAtlases, atlas)
		} else {
			removed++
		}
	}

	m.atlases = newAtlases
	return removed
}

func (m *AtlasManager) Config() AtlasConfig {
	return m.config
}

func DefaultAtlasConfig() AtlasConfig {
