func NewAtlasManager(config AtlasConfig) (*AtlasManager, error) {
	if err := config.Validate(); err != nil {
		return nil, err
	}

	// Create generator with config matching glyph size
	genConfig := DefaultConfig()
	genConfig.Size = config.GlyphSize

	return &AtlasManager{
		config:		config,
		atlases:	make([]*Atlas, 0, config.MaxAtlases),
		lookup:		make(map[GlyphKey]Region),
		generator:	NewGenerator(genConfig),
	}, nil
}

func NewAtlasManagerDefault() *AtlasManager {
	m, _ := NewAtlasManager(DefaultAtlasConfig())
	return m
}

func NewConcurrentAtlasManager(config AtlasConfig, numShards int) (*ConcurrentAtlasManager, error) {
	// Ensure numShards is power of 2
	if numShards <= 0 || (numShards&(numShards-1)) != 0 {
		numShards = 4	// Default to 4 shards
	}

	shards := make([]*AtlasManager, numShards)
	for i := range shards {
		m, err := NewAtlasManager(config)
		if err != nil {
			return nil, err
		}
		shards[i] = m
	}

	return &ConcurrentAtlasManager{
		shards:		shards,
		shardMask:	uint64(numShards - 1),	//nolint:gosec // numShards is validated to be positive power of 2
	}, nil
}

func (m *AtlasManager) Remove(key GlyphKey) bool {
	m.mu.Lock()
	defer m.mu.Unlock()

	region, ok := m.lookup[key]
	if !ok {
		return false
	}

	delete(m.lookup, key)
	if region.AtlasIndex >= 0 && region.AtlasIndex < len(m.atlases) {
		delete(m.atlases[region.AtlasIndex].regions, key)
	}

	return true
}

func (m *AtlasManager) SetGenerator(g *Generator) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.generator = g
}

func (c *ConcurrentAtlasManager) Stats() (hits, misses uint64, atlasCount int) {
	for _, shard := range c.shards {
		h, m, a := shard.Stats()
		hits += h
		misses += m
		atlasCount += a
	}
	return
}

func (a *Atlas) Utilization() float64 {
	return a.allocator.Utilization()
}

func (c *AtlasConfig) Validate() error {
	if c.Size < 64 {
		return &AtlasConfigError{Field: "Size", Reason: "must be at least 64"}
	}
	if c.Size > 8192 {
		return &AtlasConfigError{Field: "Size", Reason: "must be at most 8192"}
	}
	// Check power of 2
	if c.Size&(c.Size-1) != 0 {
		return &AtlasConfigError{Field: "Size", Reason: "must be power of 2"}
	}
	if c.GlyphSize < 8 {
		return &AtlasConfigError{Field: "GlyphSize", Reason: "must be at least 8"}
	}
	if c.GlyphSize > c.Size {
		return &AtlasConfigError{Field: "GlyphSize", Reason: "must be at most Size"}
	}
	if c.Padding < 0 {
		return &AtlasConfigError{Field: "Padding", Reason: "must be non-negative"}
	}
	if c.Padding >= c.GlyphSize/2 {
		return &AtlasConfigError{Field: "Padding", Reason: "must be less than half GlyphSize"}
	}
	if c.MaxAtlases < 1 {
		return &AtlasConfigError{Field: "MaxAtlases", Reason: "must be at least 1"}
	}
	if c.MaxAtlases > 256 {
		return &AtlasConfigError{Field: "MaxAtlases", Reason: "must be at most 256"}
	}
	return nil
}

type AtlasConfig struct {
	// Size is the atlas texture size (width = height).
	// Must be power of 2. Default: 1024
	Size	int

	// GlyphSize is the size of each glyph cell.
	// Default: 32
	GlyphSize	int

	// Padding between glyphs to prevent bleeding.
	// Default: 2
	Padding	int

	// MaxAtlases limits the number of atlases.
	// Default: 8
	MaxAtlases	int
}

type AtlasConfigError struct {
	Field	string
	Reason	string
}

type Atlas struct {
	// Data is the RGB pixel data.
	Data	[]byte

	// Size is width = height of the atlas.
	Size	int

	// Regions tracks allocated glyph regions.
	regions	map[GlyphKey]Region

	// allocator packs glyphs using grid algorithm.
	allocator	*GridAllocator

	// dirty marks if atlas needs GPU upload.
	dirty	bool

	// index is the atlas index in the manager.
	index	int

	// glyphSize is the size of each glyph cell.
	glyphSize	int
}

type Region struct {
	// AtlasIndex indicates which atlas this glyph is in.
	AtlasIndex	int

	// UV coordinates [0, 1] for texture sampling.
	// Inset by 0.5 texels to prevent bilinear bleed from adjacent cells.
	U0, V0, U1, V1	float32

	// PlaneBounds: MSDF cell extent in outline reference coordinates.
	// At render time: quad_pos = cursor + PlaneBound * (fontSize / refSize)
	PlaneMinX, PlaneMinY, PlaneMaxX, PlaneMaxY	float32

	// Pixel coordinates in atlas.
	X, Y, Width, Height	int
}

type GlyphKey struct {
	// FontID identifies the font (hash of font data or path).
	FontID	uint64

	// GlyphID is the glyph index within the font.
	GlyphID	uint16

	// Size is the MSDF texture size (not font size).
	// Different MSDF sizes produce different textures.
	Size	int16
}

type AtlasManager struct {
	mu		sync.RWMutex
	config		AtlasConfig
	atlases		[]*Atlas
	lookup		map[GlyphKey]Region
	generator	*Generator

	// Statistics (atomic for lock-free reads)
	hits	atomic.Uint64
	misses	atomic.Uint64
}

type AtlasFullError struct {
	MaxAtlases int
}

type ConcurrentAtlasManager struct {
	shards		[]*AtlasManager
	shardMask	uint64
}

func (s *Shape) AddContour(c *Contour) {
	s.Contours = append(s.Contours, c)
}

func (c *Contour) AddEdge(e Edge) {
	c.Edges = append(c.Edges, e)
}

func AssignColors(shape *Shape, angleThreshold float64) {
	for _, contour := range shape.Contours {
		if len(contour.Edges) == 0 {
			continue
		}

		assignContourColors(contour, angleThreshold)
	}
}

func (c *Contour) Bounds() Rect {
	if len(c.Edges) == 0 {
		return Rect{}
	}

	bounds := c.Edges[0].Bounds()
	for i := 1; i < len(c.Edges); i++ {
		bounds = bounds.Union(c.Edges[i].Bounds())
	}
	return bounds
}

func (s *Shape) CalculateBounds() {
	if len(s.Contours) == 0 {
		s.Bounds = Rect{}
		return
	}

	s.Bounds = s.Contours[0].Bounds()
	for i := 1; i < len(s.Contours); i++ {
		s.Bounds = s.Bounds.Union(s.Contours[i].Bounds())
	}
}

func (c *Contour) CalculateWinding() {
	// Calculate the signed area using the shoelace formula.
	// Sum up the cross products of consecutive edge endpoints.
	var area float64
	for i := range c.Edges {
		p0 := c.Edges[i].StartPoint()
		p1 := c.Edges[i].EndPoint()
		area += p0.Cross(p1)
	}
	c.Winding = area / 2
}

func (c *Contour) Clone() *Contour {
	clone := &Contour{
		Edges:		make([]Edge, len(c.Edges)),
		Winding:	c.Winding,
	}
	for i := range c.Edges {
		clone.Edges[i] = c.Edges[i].Clone()
	}
	return clone
}

func (s *Shape) EdgeCount() int {
	count := 0
	for _, c := range s.Contours {
		count += len(c.Edges)
	}
	return count
}

func FromOutline(outline *text.GlyphOutline) *Shape {
	if outline == nil || len(outline.Segments) == 0 {
		return NewShape()
	}

	shape := NewShape()
	var currentContour *Contour
	var currentPos Point

	for _, seg := range outline.Segments {
		switch seg.Op {
		case text.OutlineOpMoveTo:
			// Start a new contour
			if currentContour != nil && len(currentContour.Edges) > 0 {
				currentContour.CalculateWinding()
				shape.AddContour(currentContour)
			}
			currentContour = NewContour()
			currentPos = Point{
				X:	float64(seg.Points[0].X),
				Y:	float64(seg.Points[0].Y),
			}

		case text.OutlineOpLineTo:
			if currentContour == nil {
				currentContour = NewContour()
			}
			endPoint := Point{
				X:	float64(seg.Points[0].X),
				Y:	float64(seg.Points[0].Y),
			}
			// Skip degenerate lines
			if endPoint.Sub(currentPos).LengthSquared() > 1e-12 {
				edge := NewLinearEdge(currentPos, endPoint)
				currentContour.AddEdge(edge)
			}
			currentPos = endPoint

		case text.OutlineOpQuadTo:
			if currentContour == nil {
				currentContour = NewContour()
			}
			controlPoint := Point{
				X:	float64(seg.Points[0].X),
				Y:	float64(seg.Points[0].Y),
			}
			endPoint := Point{
				X:	float64(seg.Points[1].X),
				Y:	float64(seg.Points[1].Y),
			}
			edge := NewQuadraticEdge(currentPos, controlPoint, endPoint)
			currentContour.AddEdge(edge)
			currentPos = endPoint

		case text.OutlineOpCubicTo:
			if currentContour == nil {
				currentContour = NewContour()
			}
			control1 := Point{
				X:	float64(seg.Points[0].X),
				Y:	float64(seg.Points[0].Y),
			}
			control2 := Point{
				X:	float64(seg.Points[1].X),
				Y:	float64(seg.Points[1].Y),
			}
			endPoint := Point{
				X:	float64(seg.Points[2].X),
				Y:	float64(seg.Points[2].Y),
			}
			edge := NewCubicEdge(currentPos, control1, control2, endPoint)
			currentContour.AddEdge(edge)
			currentPos = endPoint
		}
	}

	// Add the last contour
	if currentContour != nil && len(currentContour.Edges) > 0 {
		currentContour.CalculateWinding()
		shape.AddContour(currentContour)
	}

	shape.CalculateBounds()
	return shape
}

func (c *Contour) IsClockwise() bool {
	return c.Winding < 0
}

