		Range:		4.0,
		AngleThreshold:	math.Pi / 3,	// 60 degrees
		EdgeThreshold:	1.001,
	}
}

func (p Point) Dot(q Point) float64 {
	return p.X*q.X + p.Y*q.Y
}

