	return "msdf: invalid config." + e.Field + ": " + e.Reason
}

func (r Rect) Expand(margin float64) Rect {
	return Rect{
		MinX:	r.MinX - margin,
		MinY:	r.MinY - margin,
		MaxX:	r.MaxX + margin,
		MaxY:	r.MaxY + margin,
	}
