	return int(f.font.UnitsPerEm())
}

func RasterizeGlyph(parsed ParsedFont, glyphID GlyphID, ppem float64) *GlyphImage {
	// Type assert to ximage parsed font
	xparsed, ok := parsed.(*ximageParsedFont)
	if !ok {
		return nil
	}

	// Create opentype face
	opts := &opentype.FaceOptions{
		Size:		ppem,
		DPI:		72,
		Hinting:	font.HintingFull,
	}

	otFace, err := opentype.NewFace(xparsed.font, opts)
	if err != nil {
		return nil
	}
	defer func() {
		_ = otFace.Close()
	}()

	// Get glyph bounds
	bounds, advance, ok := otFace.GlyphBounds(rune(glyphID))
	if !ok {
		return nil
	}

	// Convert fixed.Int26_6 to pixels
	minX := int(bounds.Min.X) >> 6
	minY := int(bounds.Min.Y) >> 6
	maxX := int(bounds.Max.X+63) >> 6
	maxY := int(bounds.Max.Y+63) >> 6

	// Create bounds rectangle
	rect := image.Rect(minX, minY, maxX, maxY)

	// Create alpha mask
	mask := image.NewAlpha(rect)

	// Draw glyph to mask
	drawer := &font.Drawer{
		Dst:	mask,
		Src:	image.White,
		Face:	otFace,
		Dot:	fixed.Point26_6{X: 0, Y: 0},
	}

	// Draw the glyph
	drawer.Dot = fixed.Point26_6{X: -bounds.Min.X, Y: -bounds.Min.Y}
	drawer.DrawString(string(rune(glyphID)))

	return &GlyphImage{
		Mask:		mask,
		Bounds:		rect,
		Advance:	fixedToFloat64(advance),
	}
}

type GlyphImage struct {
	// Mask is the alpha mask (grayscale image).
	// This represents the glyph's shape.
	Mask	*image.Alpha

	// Bounds relative to glyph origin.
	// The origin is typically on the baseline at the left edge.
	Bounds	image.Rectangle

	// Advance width in pixels.
	// This is how far the cursor should move after drawing this glyph.
	Advance	float64
}

func (m *RuneToBoolMap) Clear() {
	m.mu.Lock()
	defer m.mu.Unlock()

	m.blocks = make(map[uint32]*block)
}

func NewRuneToBoolMap() *RuneToBoolMap {
	return &RuneToBoolMap{
		blocks: make(map[uint32]*block),
	}
}

func (m *RuneToBoolMap) Set(r rune, hasGlyph bool) {
	m.mu.Lock()
	defer m.mu.Unlock()

	blockIdx := uint32(r) >> 8
	runeIdx := uint32(r) & 0xFF

	// Get or create block
	b, ok := m.blocks[blockIdx]
	if !ok {
		b = &block{}
		m.blocks[blockIdx] = b
	}

	// Calculate bit position
	bitIdx := runeIdx * 2
	wordIdx := bitIdx / 64
	bitPos := bitIdx % 64

	// Set checked bit (bit 0)
	b.bits[wordIdx] |= 1 << bitPos

	// Set hasGlyph bit (bit 1)
	if hasGlyph {
		b.bits[wordIdx] |= 1 << (bitPos + 1)
	} else {
		b.bits[wordIdx] &^= 1 << (bitPos + 1)
	}
}

type RuneToBoolMap struct {
	mu	sync.RWMutex
	blocks	map[uint32]*block	// Keyed by rune >> 8 (256-rune blocks)
}

func DetectScript(r rune) Script {
	// ASCII optimization for common case
	if r < 0x0080 {
		return detectASCII(r)
	}

	// Check script ranges in order of frequency/usage
	if script := detectEuropean(r); script != ScriptUnknown {
		return script
	}
	if script := detectMiddleEastern(r); script != ScriptUnknown {
		return script
	}
	if script := detectSouthAsian(r); script != ScriptUnknown {
		return script
	}
	if script := detectEastAsian(r); script != ScriptUnknown {
		return script
	}
	if script := detectSoutheastAsian(r); script != ScriptUnknown {
		return script
	}
	if script := detectOther(r); script != ScriptUnknown {
		return script
	}
	if script := detectCommonSymbols(r); script != ScriptUnknown {
		return script
	}

	return ScriptUnknown
}

func (s Script) IsRTL() bool {
	return s == ScriptArabic || s == ScriptHebrew
}

func (s Script) RequiresComplexShaping() bool {
	switch s {
	case ScriptArabic, ScriptHebrew, ScriptDevanagari, ScriptBengali,
		ScriptTamil, ScriptTelugu, ScriptKannada, ScriptMalayalam,
		ScriptGujarati, ScriptOriya, ScriptGurmukhi, ScriptSinhala,
		ScriptKhmer, ScriptLao, ScriptMyanmar, ScriptTibetan, ScriptThai:
		return true
	default:
		return false
	}
}

