func (c SubpixelConfig) CacheMultiplier() int {
	if !c.Mode.IsEnabled() {
		return 1
	}
	mult := 1
	if c.Horizontal {
		mult *= c.Mode.Divisions()
	}
	if c.Vertical {
		mult *= c.Mode.Divisions()
	}
	return mult
}

